#!/usr/bin/env python3
# Generates PROOF_evalrun.bend: LAWS.bend section 13, the stack machine (run_typed) and the entry
# points (eval_full_typed, eval_expr_typed). Hand-written lemmas as literal text; the per-kind /
# per-op / per-scalar case lists are loops.
import os
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..') + '/'
out = []
def emit(s=''):
    out.append(s)

emit('''# PROOF_evalrun.bend -- proofs of LAWS.bend section 13, the stack machine and the entry points
# (run_typed, eval_full_typed, eval_expr_typed; M5 part 2, plan M_01 P2 stage 3). Generated by
# scripts/proofgen/gen_evalrun.py (the kind / op / scalar case lists are loops).
#
# Shape: run_typed is an induction over the expression (the IH is handed to the node lemmas as a
# forall over the code suffix, the frame, the stack and its shape, `IH`); each node lemma first
# takes the analysis apart (the operand records as parameters with their equations, refuting the
# Fail rows), rewrites the law's (t, k, tot) to the record's fields through Ana injectivity, then
# runs the operand code(s) through the IH and composes one machine step (`step1` / `step2` /
# `step3`: Eval.exec on a typed state; the slot kinds are read off the stack invariant StkTy and
# the operation's typing law from PROOF_evalops supplies the result slot). A machine state is
# affine: every lemma that matches one hands the next state back as a live witness beside the
# equation `step(h, i, st) == st2` (StepW), and the two-operand steps give the operand columns to
# `fit`/`bcast` through `fit_w` (ColW witnesses). The three-operand `bad` shape test and the
# result lengths are closed terms over the three kinds once those are constructors (bad3_false,
# len3), so the when / bin steps need no case split of their own.
import Base
import ./src/dtype.bend as D
import ./src/err.bend as E
import ./src/kernels.bend as K
import ./src/column.bend as C
import ./src/schema.bend as S
import ./src/expr.bend as X
import ./src/analysis.bend as A
import ./src/eval.bend as V
import ./LAWS.bend as Laws
import ./PROOF_lib.bend as L
import ./PROOF_eval.bend as PV
import ./PROOF_evalops.bend as PO

# ---- toolkit ------------------------------------------------------------------------------------

# a run from a failed state stays failed
def run_fail(code: List<&2, V.Instr>, +h: U32, -f: C.Frame, -e: E.Err) -> {V.Eval.run(code, h, V.EvSt{f, Fail{e}}) == V.EvSt{f, Fail{e}} : V.EvSt}:
  match code:
    case Nil{}:
      {==}
    case i <> t:
      run_fail(t, h, f, e)

# Column.len with the length pinned to n (the column back, still typed)
def len_k(c: C.Column, +n: U32, +t: D.DType, hc: Laws.ColTy(t, n, c)) -> &c2: C.Column -> {C.Column.len(c) == (c2, n) : C.Column & U32} & Laws.ColTy(t, n, c2):
  match c:''')
for K in ['CBool', 'CU32', 'CI32', 'CF32', 'CStr']:
    emit('    case C.%s{+len, d, v, x}:' % K)
    emit('      (ed, +el) = hc')
    emit('      (C.%s{len, d, v, x}, (%%el : {(C.%s{len, d, v, x}, len) == (C.%s{len, d, v, x}, _) : C.Column & U32}; {==}), (ed, el))' % (K, K, K))
emit('''
# a ResW restated at an equal length (the production length is a term over the consumed column)
def resw_len(-tot: Bool, +t: D.DType, +n: U32, -n2: U32, -r0: E.ResT(C.Column), e: {n2 == n : U32}, w: Laws.ResW(tot, t, n2, r0)) -> Laws.ResW(tot, t, n, r0):
  %e : Laws.ResW(tot, t, _, r0)
  w

# a slot result: kind k, dtype t, n rows; or a failure the analysis allowed
def SlotTy(+t: D.DType, +k: V.SKind, +n: U32, s: V.Slot) -> Type:
  match s:
    case V.Slot{+k2, c}:
      {k2 == k : V.SKind} & Laws.ColTy(t, n, c)

def SResTy(+t: D.DType, +k: V.SKind, +n: U32, +tot: Bool, r: E.ResT(V.Slot)) -> Type:
  match r:
    case Fail{e}:
      {tot == False{} : Bool}
    case Done{s}:
      SlotTy(t, k, n, s)

def SResW(+t: D.DType, +k: V.SKind, +n: U32, +tot: Bool, -r0: E.ResT(V.Slot)) -> Type:
  &r: E.ResT(V.Slot) -> {r0 == r : E.ResT(V.Slot)} & SResTy(t, k, n, tot, r)

# Eval.wrap of a typed column result is a typed slot result
def wrap_k(+k: V.SKind, +t: D.DType, +n: U32, +tot: Bool, -tot2: Bool, r: E.ResT(C.Column), ty: Laws.ResTy(tot2, t, n, r), htot: @_x: {tot2 == False{} : Bool} -> {tot == False{} : Bool}) -> SResW(t, k, n, tot, V.Eval.wrap(k, r)):
  match r:
    case Fail{e}:
      (Fail{e}, {==}, htot(ty))
    case Done{c}:
      (Done{V.Slot{k, c}}, {==}, ({==}, ty))

def wrap_w(+k: V.SKind, +t: D.DType, +n: U32, +tot: Bool, -tot2: Bool, -r0: E.ResT(C.Column), w: Laws.ResW(tot2, t, n, r0), htot: @_x: {tot2 == False{} : Bool} -> {tot == False{} : Bool}) -> SResW(t, k, n, tot, V.Eval.wrap(k, r0)):
  (r, e, ty) = w
  %Equal.sym(E.ResT(C.Column), r0, r, e) : SResW(t, k, n, tot, V.Eval.wrap(k, _))
  wrap_k(k, t, n, tot, tot2, r, ty, htot)

# a total operation never fails
def tot_true(+tot: Bool, x: {True{} == False{} : Bool}) -> {tot == False{} : Bool}:
  PV.true_false_any({tot == False{} : Bool}, x)

# pushing a typed slot result onto a typed stack: the new state as a witness
def PushW(+h: U32, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, -f2: C.Frame, +sh: List<&2, Laws.Sh>, -rest: List<&1, V.Slot>, -r: E.ResT(V.Slot)) -> Type:
  &st2: V.EvSt -> {V.EvSt{f2, V.Eval.push(rest, r)} == st2 : V.EvSt} & Laws.RunTy(h, t, k, tot, f, sh, st2)

def push_s(+h: U32, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, f2: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, s: V.Slot, ef: {f2 == f : C.Frame}, hs: SlotTy(t, k, Laws.klen(k, h), s), ev: Laws.StkTy(h, sh, rest)) -> PushW(h, t, k, tot, f, f2, sh, rest, Done{s}):
  match s:
    case V.Slot{+k2, c}:
      (hk, hc) = hs
      (V.EvSt{f2, Done{V.Slot{k2, c} <> rest}}, {==}, (ef, (hk, hc, ev)))

def push_w(+h: U32, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, f2: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, r: E.ResT(V.Slot), ef: {f2 == f : C.Frame}, hr: SResTy(t, k, Laws.klen(k, h), tot, r), ev: Laws.StkTy(h, sh, rest)) -> PushW(h, t, k, tot, f, f2, sh, rest, r):
  match r:
    case Fail{e}:
      (V.EvSt{f2, Fail{e}}, {==}, hr)
    case Done{s}:
      push_s(h, t, k, tot, f, f2, sh, rest, s, ef, hr, ev)

# a slot result witness pushed: the state witness
def push_r(+h: U32, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, f2: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f2 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest), -r0: E.ResT(V.Slot), w: SResW(t, k, Laws.klen(k, h), tot, r0)) -> PushW(h, t, k, tot, f, f2, sh, rest, r0):
  (r, e, hr) = w
  %Equal.sym(E.ResT(V.Slot), r0, r, e) : PushW(h, t, k, tot, f, f2, sh, rest, _)
  push_w(h, t, k, tot, f, f2, sh, rest, r, ef, hr, ev)

# ---- Ana injectivity --------------------------------------------------------------------------------

def ana_tot(a: A.Ana) -> Bool:
  match a:
    case A.Ana{t, rs, k, tot, loc}:
      tot

def ana_t_inj(-t1: D.DType, -rs1: List<&2, String>, -k1: A.AKind, -tot1: Bool, -loc1: Bool, -t2: D.DType, -rs2: List<&2, String>, -k2: A.AKind, -tot2: Bool, -loc2: Bool, e: {A.Ana{t1, rs1, k1, tot1, loc1} == A.Ana{t2, rs2, k2, tot2, loc2} : A.Ana}) -> {t1 == t2 : D.DType}:
  Equal.cong(A.Ana, D.DType, a => A.Ana.dtype(a), A.Ana{t1, rs1, k1, tot1, loc1}, A.Ana{t2, rs2, k2, tot2, loc2}, e)

def ana_k_inj(-t1: D.DType, -rs1: List<&2, String>, -k1: A.AKind, -tot1: Bool, -loc1: Bool, -t2: D.DType, -rs2: List<&2, String>, -k2: A.AKind, -tot2: Bool, -loc2: Bool, e: {A.Ana{t1, rs1, k1, tot1, loc1} == A.Ana{t2, rs2, k2, tot2, loc2} : A.Ana}) -> {k1 == k2 : A.AKind}:
  Equal.cong(A.Ana, A.AKind, a => A.Ana.kind(a), A.Ana{t1, rs1, k1, tot1, loc1}, A.Ana{t2, rs2, k2, tot2, loc2}, e)

def ana_tot_inj(-t1: D.DType, -rs1: List<&2, String>, -k1: A.AKind, -tot1: Bool, -loc1: Bool, -t2: D.DType, -rs2: List<&2, String>, -k2: A.AKind, -tot2: Bool, -loc2: Bool, e: {A.Ana{t1, rs1, k1, tot1, loc1} == A.Ana{t2, rs2, k2, tot2, loc2} : A.Ana}) -> {tot1 == tot2 : Bool}:
  Equal.cong(A.Ana, Bool, a => ana_tot(a), A.Ana{t1, rs1, k1, tot1, loc1}, A.Ana{t2, rs2, k2, tot2, loc2}, e)

# the stack machine's kind of a joined analysis kind is the combination of the kinds
def skind_join(ka: A.AKind, kb: A.AKind) -> {Laws.skind(A.AKind.join(ka, kb)) == V.SKind.comb(Laws.skind(ka), Laws.skind(kb)) : V.SKind}:
  match ka kb:''')
for ka in ['KRow', 'KScalar', 'KRed']:
    for kb in ['KRow', 'KScalar', 'KRed']:
        emit('    case A.%s{} A.%s{}:' % (ka, kb))
        emit('      {==}')
emit('''
# ---- one machine step on a typed state --------------------------------------------------------------

def StepW(+h: U32, +i: V.Instr, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, -st: V.EvSt) -> Type:
  &st2: V.EvSt -> {V.Eval.step(h, i, st) == st2 : V.EvSt} & Laws.RunTy(h, t, k, tot, f, sh, st2)

# a RunW for `i <> acc` composed with a step for i is a RunW for acc
def run_step(+h: U32, +i: V.Instr, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, -st: V.EvSt,
  eq: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(i <> acc, h, st) : V.EvSt}, w: StepW(h, i, t, k, tot, f, sh, st)) -> Laws.RunW(h, t, k, tot, f, sh, stk, acc, code):
  (st2, es, ty) = w
  (st2, (%es : {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(acc, h, _) : V.EvSt}; eq), ty)

# the same with the run split at an intermediate state (two- and three-operand nodes)
def run_step2(+h: U32, +i: V.Instr, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, -code1: List<&2, V.Instr>, -st1: V.EvSt, -st: V.EvSt,
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(code1, h, st1) : V.EvSt}, eq: {V.Eval.run(code1, h, st1) == V.Eval.run(i <> acc, h, st) : V.EvSt}, w: StepW(h, i, t, k, tot, f, sh, st)) -> Laws.RunW(h, t, k, tot, f, sh, stk, acc, code):
  (st2, es, ty) = w
  (st2, Equal.trans(V.EvSt, V.Eval.run(code, h, V.EvSt{f, Done{stk}}), V.Eval.run(code1, h, st1), V.Eval.run(acc, h, st2), eq1, (%es : {V.Eval.run(code1, h, st1) == V.Eval.run(acc, h, _) : V.EvSt}; eq)), ty)

# an operand whose run failed: the rest of the code keeps the failure, which the analysis allowed
def run_failed(+h: U32, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, code1: List<&2, V.Instr>, f2: C.Frame, e: E.Err,
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(code1, h, V.EvSt{f2, Fail{e}}) : V.EvSt}, htot: {tot == False{} : Bool}) -> Laws.RunW(h, t, k, tot, f, sh, stk, acc, code):
  (V.EvSt{f2, Fail{e}}, Equal.trans(V.EvSt, V.Eval.run(code, h, V.EvSt{f, Done{stk}}), V.Eval.run(code1, h, V.EvSt{f2, Fail{e}}), V.Eval.run(acc, h, V.EvSt{f2, Fail{e}}), eq1, Equal.trans(V.EvSt, V.Eval.run(code1, h, V.EvSt{f2, Fail{e}}), V.EvSt{f2, Fail{e}}, V.Eval.run(acc, h, V.EvSt{f2, Fail{e}}), run_fail(code1, h, f2, e), Equal.sym(V.EvSt, V.Eval.run(acc, h, V.EvSt{f2, Fail{e}}), V.EvSt{f2, Fail{e}}, run_fail(acc, h, f2, e)))), htot)

# the IH as a hypothesis: the operand's code from any typed frame / stack
def IH(+e: X.Expr, +s: List<&2, S.Field>, +h: U32) -> Type:
  @acc: List<&2, V.Instr> -> @f: C.Frame -> @stk: List<&1, V.Slot> -> @sh: List<&2, Laws.Sh> -> @hs: {Laws.fschema(f) == s : List<&2, S.Field>} -> @hf: {Laws.frame_ok(h, f) == True{} : Bool} -> @ev: Laws.StkTy(h, sh, stk) -> @t: D.DType -> @rs: List<&2, String> -> @k: A.AKind -> @tot: Bool -> @loc: Bool -> @ha: {A.Expr.analyse(e, s) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)} -> Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile(e, acc))

# the frame facts restated over an equal frame
def hs_along(-f: C.Frame, -f2: C.Frame, +s: List<&2, S.Field>, ef: {f2 == f : C.Frame}, hs: {Laws.fschema(f) == s : List<&2, S.Field>}) -> {Laws.fschema(f2) == s : List<&2, S.Field>}:
  %Equal.sym(C.Frame, f2, f, ef) : {Laws.fschema(_) == s : List<&2, S.Field>}
  hs

def hf_along(-f: C.Frame, -f2: C.Frame, +h: U32, ef: {f2 == f : C.Frame}, hf: {Laws.frame_ok(h, f) == True{} : Bool}) -> {Laws.frame_ok(h, f2) == True{} : Bool}:
  %Equal.sym(C.Frame, f2, f, ef) : {Laws.frame_ok(h, _) == True{} : Bool}
  hf

# ---- one-operand instructions (Eval.app1 / do1) ----------------------------------------------------

def step1_d(+h: U32, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, f2: C.Frame, rest: List<&1, V.Slot>, ef: {f2 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest), -r0: E.ResT(V.Slot), w: SResW(t, k, Laws.klen(k, h), tot, r0))
  -> PushW(h, t, k, tot, f, f2, sh, rest, r0):
  push_r(h, t, k, tot, f, f2, sh, rest, ef, ev, r0, w)

def step1_c(+h: U32, +i: V.Instr, +t2: D.DType, +k2: V.SKind, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, f2: C.Frame, k3: V.SKind, c: C.Column, rest: List<&1, V.Slot>,
  ef: {f2 == f : C.Frame}, hk: {k3 == k2 : V.SKind}, hc: Laws.ColTy(t2, Laws.klen(k2, h), c), ev: Laws.StkTy(h, sh, rest),
  stepc: @c4: C.Column -> @hc4: Laws.ColTy(t2, Laws.klen(k2, h), c4) -> SResW(t, k, Laws.klen(k, h), tot, V.Eval.do1(h, i, k2, c4)))
  -> &st2: V.EvSt -> {V.EvSt{f2, V.Eval.app1(h, i, V.Slot{k3, c} <> rest)} == st2 : V.EvSt} & Laws.RunTy(h, t, k, tot, f, sh, st2):
  %Equal.sym(V.SKind, k3, k2, hk) : &st2: V.EvSt -> {V.EvSt{f2, V.Eval.push(rest, V.Eval.do1(h, i, _, c))} == st2 : V.EvSt} & Laws.RunTy(h, t, k, tot, f, sh, st2)
  step1_d(h, t, k, tot, f, sh, f2, rest, ef, ev, V.Eval.do1(h, i, k2, c), stepc(c, hc))

def step1_b(+h: U32, +i: V.Instr, +t2: D.DType, +k2: V.SKind, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, f2: C.Frame, stk2: List<&1, V.Slot>,
  ty: {f2 == f : C.Frame} & Laws.StkTy(h, Laws.Sh{t2, k2} <> sh, stk2),
  hex: @-f3: C.Frame -> @-stk3: List<&1, V.Slot> -> {V.Eval.exec(h, i, f3, stk3) == V.EvSt{f3, V.Eval.app1(h, i, stk3)} : V.EvSt},
  stepc: @c4: C.Column -> @hc4: Laws.ColTy(t2, Laws.klen(k2, h), c4) -> SResW(t, k, Laws.klen(k, h), tot, V.Eval.do1(h, i, k2, c4)))
  -> StepW(h, i, t, k, tot, f, sh, V.EvSt{f2, Done{stk2}}):
  match stk2:
    case Nil{}:
      (ef, ev) = ty
      Empty.absurd(StepW(h, i, t, k, tot, f, sh, V.EvSt{f2, Done{Nil{}}}), ev)
    case V.Slot{+k3, c} <> rest:
      (ef, hk, hc, ev) = ty
      %Equal.sym(V.EvSt, V.Eval.exec(h, i, f2, V.Slot{k3, c} <> rest), V.EvSt{f2, V.Eval.app1(h, i, V.Slot{k3, c} <> rest)}, hex(f2, V.Slot{k3, c} <> rest)) : &st2: V.EvSt -> {_ == st2 : V.EvSt} & Laws.RunTy(h, t, k, tot, f, sh, st2)
      step1_c(h, i, t2, k2, t, k, tot, f, sh, f2, k3, c, rest, ef, hk, hc, ev, stepc)

def step1_a(+h: U32, +i: V.Instr, +t2: D.DType, +k2: V.SKind, +tot2: Bool, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, f2: C.Frame, r: E.ResT(List<&1, V.Slot>),
  ty: Laws.ResSt(h, t2, k2, tot2, f, sh, f2, r),
  hex: @-f3: C.Frame -> @-stk3: List<&1, V.Slot> -> {V.Eval.exec(h, i, f3, stk3) == V.EvSt{f3, V.Eval.app1(h, i, stk3)} : V.EvSt},
  stepc: @c4: C.Column -> @hc4: Laws.ColTy(t2, Laws.klen(k2, h), c4) -> SResW(t, k, Laws.klen(k, h), tot, V.Eval.do1(h, i, k2, c4)),
  htot: @_x: {tot2 == False{} : Bool} -> {tot == False{} : Bool})
  -> StepW(h, i, t, k, tot, f, sh, V.EvSt{f2, r}):
  match r:
    case Fail{e}:
      (V.EvSt{f2, Fail{e}}, {==}, htot(ty))
    case Done{stk2}:
      step1_b(h, i, t2, k2, t, k, tot, f, sh, f2, stk2, ty, hex, stepc)

# one unary instruction (IUn / ICast / ITry / IAgg / IIsIn / IClip / IStr) on a typed state
def step1(+h: U32, +i: V.Instr, +t2: D.DType, +k2: V.SKind, +tot2: Bool, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, st: V.EvSt,
  ty: Laws.RunTy(h, t2, k2, tot2, f, sh, st),
  hex: @-f3: C.Frame -> @-stk3: List<&1, V.Slot> -> {V.Eval.exec(h, i, f3, stk3) == V.EvSt{f3, V.Eval.app1(h, i, stk3)} : V.EvSt},
  stepc: @c4: C.Column -> @hc4: Laws.ColTy(t2, Laws.klen(k2, h), c4) -> SResW(t, k, Laws.klen(k, h), tot, V.Eval.do1(h, i, k2, c4)),
  htot: @_x: {tot2 == False{} : Bool} -> {tot == False{} : Bool})
  -> StepW(h, i, t, k, tot, f, sh, st):
  match st:
    case V.EvSt{f2, r}:
      step1_a(h, i, t2, k2, tot2, t, k, tot, f, sh, f2, r, ty, hex, stepc, htot)

# a unary node: the operand's RunW for `i <> acc` and the step for i
def un_run(+h: U32, +i: V.Instr, +t2: D.DType, +k2: V.SKind, +tot2: Bool, +t: D.DType, +k: V.SKind, +tot: Bool, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>,
  w: Laws.RunW(h, t2, k2, tot2, f, sh, stk, i <> acc, code),
  hex: @-f3: C.Frame -> @-stk3: List<&1, V.Slot> -> {V.Eval.exec(h, i, f3, stk3) == V.EvSt{f3, V.Eval.app1(h, i, stk3)} : V.EvSt},
  stepc: @c4: C.Column -> @hc4: Laws.ColTy(t2, Laws.klen(k2, h), c4) -> SResW(t, k, Laws.klen(k, h), tot, V.Eval.do1(h, i, k2, c4)),
  htot: @_x: {tot2 == False{} : Bool} -> {tot == False{} : Bool}) -> Laws.RunW(h, t, k, tot, f, sh, stk, acc, code):
  (st, eq, ty) = w
  run_step(h, i, t, k, tot, f, sh, stk, acc, code, st, eq, step1(h, i, t2, k2, tot2, t, k, tot, f, sh, st, ty, hex, stepc, htot))
''')

# ---- the single-operand nodes whose kind / totality is the operand's: Un, IsIn, Clip, StrPred ---------
# (name, extra params, instr term, analysis fn applied to r, dtype rule over t2, eval law call with hok', Eval op term)
UNARY = [
    ('un', '+op: X.UnOp', 'op', 'V.IUn{op}', 'A.Ana.un(op, r)', 'X.Expr.type.un.ok(op, t2)', 'X.Expr.type.un.ok(op, _)',
     'Laws.eval_un_typed(op, c, t, HOK)', 'V.Eval.un(op, c)'),
    ('isin', '+vs: List<&2, D.Scalar>', 'vs', 'V.IIsIn{vs}', 'A.Ana.isin(vs, r)', 'X.Expr.type.isin.ok(vs, t2)', 'X.Expr.type.isin.ok(vs, _)',
     'Laws.eval_isin_typed(vs, c, t, HOK)', 'V.Eval.isin(vs, c)'),
    ('clip', '+lo: D.Scalar, +hi: D.Scalar', 'lo, hi', 'V.IClip{lo, hi}', 'A.Ana.clip(lo, hi, r)', 'X.Expr.type.clip.ok(lo, hi, t2)', 'X.Expr.type.clip.ok(lo, hi, _)',
     'Laws.eval_clip_typed(lo, hi, c, t, HOK)', 'V.Eval.clip(lo, hi, c)'),
    ('strpred', '+op: X.StrPredOp, +p: String', 'op, p', 'V.IStr{op, p}', 'A.Ana.strpred(op, r)', 'X.Expr.type.strpred.ok(op, t2)', 'X.Expr.type.strpred.ok(op, _)',
     'Laws.eval_strpred_typed(op, p, c, t, HOK)', 'V.Eval.strpred(op, p, c)'),
]
COMMON = '+s: List<&2, S.Field>, +h: U32, +acc: List<&2, V.Instr>, f: C.Frame, stk: List<&1, V.Slot>, +sh: List<&2, Laws.Sh>, +hs: {Laws.fschema(f) == s : List<&2, S.Field>}, +hf: {Laws.frame_ok(h, f) == True{} : Bool}, ev: Laws.StkTy(h, sh, stk), +t: D.DType, +rs: List<&2, String>, +k: A.AKind, +tot: Bool, +loc: Bool'
COMMON_ARGS = 's, h, acc, f, stk, sh, hs, hf, ev, t, rs, k, tot, loc'
REC = '+t2: D.DType, +rs2: List<&2, String>, +k2: A.AKind, +tot2: Bool, +loc2: Bool'
REC_ARGS = 't2, rs2, k2, tot2, loc2'

for (nm, extra, xargs, instr, ana, rule, rule_hole, law, evop) in UNARY:
    goal = 'Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile(e2, %s <> acc))' % instr
    hok = "(%%Equal.sym(D.DType, Laws.cdtype(c), t2, ed) : {%s == Done{t} : E.Res(D.DType)}; hok)" % rule_hole
    emit('# ---- %s ----' % nm)
    emit('')
    emit('# the step: the operation on a typed column')
    emit('def %s_stepc(%s, +t2: D.DType, +k2: V.SKind, +h: U32, +t: D.DType, +tot: Bool, hok: {%s == Done{t} : E.Res(D.DType)}, c: C.Column, hc: Laws.ColTy(t2, Laws.klen(k2, h), c)) -> SResW(t, k2, Laws.klen(k2, h), tot, V.Eval.do1(h, %s, k2, c)):' % (nm, extra, rule, instr))
    emit('  (ed, el) = hc')
    emit('  wrap_w(k2, t, Laws.klen(k2, h), tot, True{}, %s, resw_len(True{}, t, Laws.klen(k2, h), Laws.clen(c), %s, el, %s), x => tot_true(tot, x))' % (evop, evop, law.replace('HOK', hok)))
    emit('')
    emit('# the dtype rule answered Done{t3}: the law\'s record is (t3, k2, tot2); run the operand and step')
    emit('def %s_ana_k(%s, +e2: X.Expr, %s,' % (nm, extra, COMMON))
    emit('  %s, rt: E.Res(D.DType), +ert: {%s == rt : E.Res(D.DType)},' % (REC, rule))
    emit('  +er: {A.Expr.analyse(e2, s) == Done{A.Ana{%s}} : E.Res(A.Ana)}, ha: {A.Ana.mk(rt, rs2, k2, tot2, loc2) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h))' % REC_ARGS)
    emit('  -> %s:' % goal)
    emit('  match rt:')
    emit('    case Fail{e}:')
    emit('      Empty.absurd(%s, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))' % goal)
    emit('    case Done{+t3}:')
    emit('      +ea = L.done_inj(A.Ana, A.Ana{t3, rs2, k2, tot2, loc2}, A.Ana{t, rs, k, tot, loc}, ha)')
    emit('      %%ana_k_inj(t3, rs2, k2, tot2, loc2, t, rs, k, tot, loc, ea) : %s' % goal.replace('Laws.skind(k)', 'Laws.skind(_)'))
    emit('      %%ana_tot_inj(t3, rs2, k2, tot2, loc2, t, rs, k, tot, loc, ea) : %s' % goal.replace('Laws.skind(k), tot,', 'Laws.skind(k2), _,'))
    emit('      %%ana_t_inj(t3, rs2, k2, tot2, loc2, t, rs, k, tot, loc, ea) : %s' % goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, _, Laws.skind(k2), tot2,'))
    emit('      un_run(h, %s, t2, Laws.skind(k2), tot2, t3, Laws.skind(k2), tot2, f, sh, stk, acc, V.Eval.compile(e2, %s <> acc), ih(%s <> acc, f, stk, sh, hs, hf, ev, %s, er), f3 => stk3 => {==}, c4 => hc4 => %s_stepc(%s, t2, Laws.skind(k2), h, t3, tot2, ert, c4, hc4), x => x)' % (instr, instr, instr, REC_ARGS, nm, xargs))
    emit('')
    emit('# the node: the operand record r (Fail refuted), then the dtype rule')
    emit('def %s_ana(%s, +e2: X.Expr, %s,' % (nm, extra, COMMON))
    emit('  r: E.Res(A.Ana), +er: {A.Expr.analyse(e2, s) == r : E.Res(A.Ana)}, ha: {%s == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h))' % ana)
    emit('  -> %s:' % goal)
    emit('  match r:')
    emit('    case Fail{e}:')
    emit('      Empty.absurd(%s, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))' % goal)
    emit('    case Done{A.Ana{%s}}:' % ', '.join('+' + x for x in REC_ARGS.split(', ')))
    emit('      %s_ana_k(%s, e2, %s, %s, %s, {==}, er, ha, ih)' % (nm, xargs, COMMON_ARGS, REC_ARGS, rule))
    emit('')


# ---- Col ---------------------------------------------------------------------------------------------
emit("""# ---- Col: ICol clones the column the schema names (get_cloned_typed) ------------------------------------

def col_fin(+n: String, +h: U32, +acc: List<&2, V.Instr>, -f: C.Frame, stk: List<&1, V.Slot>, +sh: List<&2, Laws.Sh>, ev: Laws.StkTy(h, sh, stk), +t2: D.DType, w: Laws.GetW(f, n, h, t2)) -> Laws.RunW(h, t2, V.KFull{}, True{}, f, sh, stk, acc, V.ICol{n} <> acc):
  (f2, c, eg, ef, ty) = w
  %Equal.sym(C.Frame & E.ResT(C.Column), C.Frame.get_cloned(f, n), (f2, Done{c}), eg) : &st: V.EvSt -> {V.Eval.run(acc, h, V.Eval.push_col(stk, _)) == V.Eval.run(acc, h, st) : V.EvSt} & Laws.RunTy(h, t2, V.KFull{}, True{}, f, sh, st)
  (V.EvSt{f2, Done{V.Slot{V.KFull{}, c} <> stk}}, {==}, ef, {==}, ty, ev)

def col_ana(+n: String, """ + COMMON + """,
  m: Maybe<&2, D.DType>, +em: {S.Schema.find(s, n) == m : Maybe<&2, D.DType>}, ha: {A.Ana.col(n, m) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)})
  -> Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.ICol{n} <> acc):
  match m:
    case None{}:
      Empty.absurd(Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.ICol{n} <> acc), L.fail_done(A.Ana, E.ColumnNotFound{n}, A.Ana{t, rs, k, tot, loc}, ha))
    case Some{+t2}:
      +ea = L.done_inj(A.Ana, A.Ana{t2, n <> Nil{}, A.KRow{}, True{}, True{}}, A.Ana{t, rs, k, tot, loc}, ha)
      %ana_k_inj(t2, n <> Nil{}, A.KRow{}, True{}, True{}, t, rs, k, tot, loc, ea) : Laws.RunW(h, t, Laws.skind(_), tot, f, sh, stk, acc, V.ICol{n} <> acc)
      %ana_tot_inj(t2, n <> Nil{}, A.KRow{}, True{}, True{}, t, rs, k, tot, loc, ea) : Laws.RunW(h, t, V.KFull{}, _, f, sh, stk, acc, V.ICol{n} <> acc)
      %ana_t_inj(t2, n <> Nil{}, A.KRow{}, True{}, True{}, t, rs, k, tot, loc, ea) : Laws.RunW(h, _, V.KFull{}, True{}, f, sh, stk, acc, V.ICol{n} <> acc)
      col_fin(n, h, acc, f, stk, sh, ev, t2, Laws.get_cloned_typed(f, n, h, t2, hf, (%Equal.sym(List<&2, S.Field>, Laws.fschema(f), s, hs) : {S.Schema.find(_, n) == Some{t2} : Maybe<&2, D.DType>}; em)))

# ---- Lit: IConst pushes a one-row literal slot (unit_typed) ----------------------------------------------

def lit_ana(+v: D.Scalar, +h: U32, +acc: List<&2, V.Instr>, f: C.Frame, stk: List<&1, V.Slot>, +sh: List<&2, Laws.Sh>, ev: Laws.StkTy(h, sh, stk), +t: D.DType, +rs: List<&2, String>, +k: A.AKind, +tot: Bool, +loc: Bool,
  ha: {A.Ana.lit(v) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}) -> Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile.lit(v) <> acc):
  match v:
    case D.SNull{}:
      Empty.absurd(Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile.lit(D.SNull{}) <> acc), L.fail_done(A.Ana, E.TypeMismatch{"lit", "a typed literal", "null"}, A.Ana{t, rs, k, tot, loc}, ha))""")
for (K, field, DT) in [('SBool', 'b', 'D.TBool{}'), ('SU32', 'x', 'D.TU32{}'), ('SI32', 'x', 'D.TI32{}'), ('SF32', 'x', 'D.TF32{}'), ('SStr', 'x', 'D.TStr{}')]:
    sc = 'D.%s{%s}' % (K, field)
    goal = 'Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile.lit(%s) <> acc)' % sc
    rec = '%s, Nil{}, A.KScalar{}, True{}, True{}' % DT
    emit('    case %s:' % sc)
    emit('      +ea = L.done_inj(A.Ana, A.Ana{%s}, A.Ana{t, rs, k, tot, loc}, ha)' % rec)
    emit('      %%ana_k_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, goal.replace('Laws.skind(k)', 'Laws.skind(_)')))
    emit('      %%ana_tot_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, goal.replace('Laws.skind(k), tot,', 'V.KLit{}, _,')))
    emit('      %%ana_t_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, _, V.KLit{}, True{},')))
    emit('      (V.EvSt{f, Done{V.Slot{V.KLit{}, V.Eval.unit(%s, %s)} <> stk}}, {==}, {==}, {==}, Laws.unit_typed(%s, %s), ev)' % (sc, DT, sc, DT))
emit('')

# ---- Cast / TryCast -----------------------------------------------------------------------------------
emit("""# ---- Cast / TryCast: the typed null literal is an IConst; otherwise the operand then ICast / ITry -----

# the step for a strict cast: Eval.cast may fail exactly when the pair is fallible (eval_cast_typed)
def cast_stepc(+to: D.DType, +t2: D.DType, +k2: V.SKind, +h: U32, +tot2: Bool, hok: {X.Cast.ok(t2, to) == True{} : Bool}, c: C.Column, hc: Laws.ColTy(t2, Laws.klen(k2, h), c)) -> SResW(to, k2, Laws.klen(k2, h), Bool.and(tot2, X.Cast.total(t2, to)), V.Eval.do1(h, V.ICast{to}, k2, c)):
  (+ed, el) = hc
  wrap_w(k2, to, Laws.klen(k2, h), Bool.and(tot2, X.Cast.total(t2, to)), X.Cast.total(Laws.cdtype(c), to), V.Eval.cast(to, c), resw_len(X.Cast.total(Laws.cdtype(c), to), to, Laws.klen(k2, h), Laws.clen(c), V.Eval.cast(to, c), el, Laws.eval_cast_typed(to, c, (%Equal.sym(D.DType, Laws.cdtype(c), t2, ed) : {X.Cast.ok(_, to) == True{} : Bool}; hok))), x => (%ed : {Bool.and(tot2, X.Cast.total(_, to)) == False{} : Bool}; (%Equal.sym(Bool, X.Cast.total(Laws.cdtype(c), to), False{}, x) : {Bool.and(tot2, _) == False{} : Bool}; PV.and_false_r(tot2))))

# the step for try_cast: never fails on a castable pair
def trycast_stepc(+to: D.DType, +t2: D.DType, +k2: V.SKind, +h: U32, +tot2: Bool, hok: {X.Cast.ok(t2, to) == True{} : Bool}, c: C.Column, hc: Laws.ColTy(t2, Laws.klen(k2, h), c)) -> SResW(to, k2, Laws.klen(k2, h), tot2, V.Eval.do1(h, V.ITry{to}, k2, c)):
  (ed, el) = hc
  wrap_w(k2, to, Laws.klen(k2, h), tot2, True{}, V.Eval.try_cast(to, c), resw_len(True{}, to, Laws.klen(k2, h), Laws.clen(c), V.Eval.try_cast(to, c), el, Laws.eval_try_cast_typed(to, c, (%Equal.sym(D.DType, Laws.cdtype(c), t2, ed) : {X.Cast.ok(_, to) == True{} : Bool}; hok))), x => tot_true(tot2, x))

# a fallible operand makes the strict cast fallible
def cast_htot(+tot2: Bool, +t2: D.DType, +to: D.DType, x: {tot2 == False{} : Bool}) -> {Bool.and(tot2, X.Cast.total(t2, to)) == False{} : Bool}:
  %Equal.sym(Bool, tot2, False{}, x) : {Bool.and(_, X.Cast.total(t2, to)) == False{} : Bool}
  {==}
""")
for (nm, try_, instr, rule_fn, stepc, TOT, htot_term) in [
    ('cast', 'False{}', 'V.ICast{to}', 'X.Expr.type.cast', 'cast_stepc', 'Bool.and(tot2, X.Cast.total(t2, to))', 'x => cast_htot(tot2, t2, to, x)'),
    ('trycast', 'True{}', 'V.ITry{to}', 'X.Expr.type.trycast', 'trycast_stepc', 'tot2', 'x => x')]:
    goal = 'Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile(e2, %s <> acc))' % instr
    emit('# the castability test answered ok: the record is (to, k2, %s); run the operand and step' % TOT)
    emit('def %s_ana_k(+to: D.DType, +e2: X.Expr, %s,' % (nm, COMMON))
    emit('  %s, ok: Bool, +eok: {X.Cast.ok(t2, to) == ok : Bool},' % REC)
    emit('  +er: {A.Expr.analyse(e2, s) == Done{A.Ana{%s}} : E.Res(A.Ana)}, ha: {A.Ana.mk(X.Expr.chk(ok, E.TypeMismatch{"%s", "castable to " ++ D.DType.show(to), D.DType.show(t2)}, Done{to}), rs2, k2, %s, loc2) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h))' % (REC_ARGS, 'cast' if nm == 'cast' else 'try_cast', TOT))
    emit('  -> %s:' % goal)
    emit('  match ok:')
    emit('    case False{}:')
    emit('      Empty.absurd(%s, L.fail_done(A.Ana, E.TypeMismatch{"%s", "castable to " ++ D.DType.show(to), D.DType.show(t2)}, A.Ana{t, rs, k, tot, loc}, ha))' % (goal, 'cast' if nm == 'cast' else 'try_cast'))
    emit('    case True{}:')
    emit('      +ea = L.done_inj(A.Ana, A.Ana{to, rs2, k2, %s, loc2}, A.Ana{t, rs, k, tot, loc}, ha)' % TOT)
    emit('      %%ana_k_inj(to, rs2, k2, %s, loc2, t, rs, k, tot, loc, ea) : %s' % (TOT, goal.replace('Laws.skind(k)', 'Laws.skind(_)')))
    emit('      %%ana_tot_inj(to, rs2, k2, %s, loc2, t, rs, k, tot, loc, ea) : %s' % (TOT, goal.replace('Laws.skind(k), tot,', 'Laws.skind(k2), _,')))
    emit('      %%ana_t_inj(to, rs2, k2, %s, loc2, t, rs, k, tot, loc, ea) : %s' % (TOT, goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, _, Laws.skind(k2), %s,' % TOT)))
    emit('      un_run(h, %s, t2, Laws.skind(k2), tot2, to, Laws.skind(k2), %s, f, sh, stk, acc, V.Eval.compile(e2, %s <> acc), ih(%s <> acc, f, stk, sh, hs, hf, ev, %s, er), f3 => stk3 => {==}, c4 => hc4 => %s(to, t2, Laws.skind(k2), h, tot2, eok, c4, hc4), %s)' % (instr, TOT, instr, instr, REC_ARGS, stepc, htot_term))
    emit('')
    emit('# not the null literal: the operand record r (Fail refuted), then the castability test')
    emit('def %s_ana_r(+to: D.DType, +e2: X.Expr, %s,' % (nm, COMMON))
    emit('  r: E.Res(A.Ana), +er: {A.Expr.analyse(e2, s) == r : E.Res(A.Ana)}, ha: {A.Ana.cast(%s, False{}, to, r) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h))' % try_)
    emit('  -> %s:' % goal)
    emit('  match r:')
    emit('    case Fail{e}:')
    emit('      Empty.absurd(%s, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))' % goal)
    emit('    case Done{A.Ana{%s}}:' % ', '.join('+' + x for x in REC_ARGS.split(', ')))
    emit('      %s_ana_k(to, e2, %s, %s, X.Cast.ok(t2, to), {==}, er, ha, ih)' % (nm, COMMON_ARGS, REC_ARGS))
    emit('')
    emit('# the node: the typed null literal Cast{Lit{SNull}, to} is a one-row IConst of dtype `to`')
    emit('def %s_ana(+to: D.DType, +e2: X.Expr, %s,' % (nm, COMMON))
    emit('  nl: Bool, r: E.Res(A.Ana), +er: {A.Expr.analyse(e2, s) == r : E.Res(A.Ana)}, ha: {A.Ana.cast(%s, nl, to, r) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h))' % try_)
    emit('  -> Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile.cast(nl, to, acc, V.Eval.compile(e2, %s <> acc))):' % instr)
    emit('  match nl:')
    emit('    case True{}:')
    g2 = 'Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.IConst{D.SNull{}, to} <> acc)'
    rec = 'to, Nil{}, A.KScalar{}, True{}, True{}'
    emit('      +ea = L.done_inj(A.Ana, A.Ana{%s}, A.Ana{t, rs, k, tot, loc}, ha)' % rec)
    emit('      %%ana_k_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, g2.replace('Laws.skind(k)', 'Laws.skind(_)')))
    emit('      %%ana_tot_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, g2.replace('Laws.skind(k), tot,', 'V.KLit{}, _,')))
    emit('      %%ana_t_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, g2.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, _, V.KLit{}, True{},')))
    emit('      (V.EvSt{f, Done{V.Slot{V.KLit{}, V.Eval.unit(D.SNull{}, to)} <> stk}}, {==}, {==}, {==}, Laws.unit_typed(D.SNull{}, to), ev)')
    emit('    case False{}:')
    emit('      %s_ana_r(to, e2, %s, r, er, ha, ih)' % (nm, COMMON_ARGS))
    emit('')


# ---- Agg -------------------------------------------------------------------------------------------------
AGGS = ['Sum', 'Mean', 'Min', 'Max', 'Count', 'Len', 'First', 'Last', 'NUnique', 'Std', 'Var', 'Median']
emit("""# ---- Agg: IAgg reduces the operand to one row (eval_agg_typed); Len over a literal broadcasts first ----

# the step on a full column: fit_agg leaves it alone (fit_len(KFull) too)
def agg_stepc_full(op: X.AggOp, +t2: D.DType, +h: U32, +t: D.DType, +tot: Bool, hok: {X.Expr.type.agg.ok(op, t2) == Done{t} : E.Res(D.DType)}, c: C.Column, hc: Laws.ColTy(t2, Laws.klen(V.KFull{}, h), c)) -> SResW(t, V.KAgg{}, Laws.klen(V.KAgg{}, h), tot, V.Eval.do1(h, V.IAgg{op}, V.KFull{}, c)):
  match op:""")
for op in AGGS:
    emit('    case X.%s{}:' % op)
    emit('      (ed, el) = hc')
    emit('      wrap_w(V.KAgg{}, t, 1, tot, True{}, V.Eval.agg(X.%s{}, c), Laws.eval_agg_typed(X.%s{}, c, t, (%%Equal.sym(D.DType, Laws.cdtype(c), t2, ed) : {X.Expr.type.agg.ok(X.%s{}, _) == Done{t} : E.Res(D.DType)}; hok)), x => tot_true(tot, x))' % (op, op, op))
emit("""
# Len over a one-row literal: the literal is broadcast to the height first (bcast_typed), then counted
def agg_len_lit(+t2: D.DType, +h: U32, +t: D.DType, +tot: Bool, hok: {X.Expr.type.agg.ok(X.Len{}, t2) == Done{t} : E.Res(D.DType)}, -c: C.Column, ed: {Laws.cdtype(c) == t2 : D.DType}, w: Laws.ColW(Laws.cdtype(c), h, V.Eval.bcast(c, h))) -> SResW(t, V.KAgg{}, 1, tot, V.Eval.wrap(V.KAgg{}, V.Eval.agg(X.Len{}, V.Eval.bcast(c, h)))):
  (c2, eb, ed2, el2) = w
  %Equal.sym(C.Column, V.Eval.bcast(c, h), c2, eb) : SResW(t, V.KAgg{}, 1, tot, V.Eval.wrap(V.KAgg{}, V.Eval.agg(X.Len{}, _)))
  wrap_w(V.KAgg{}, t, 1, tot, True{}, V.Eval.agg(X.Len{}, c2), Laws.eval_agg_typed(X.Len{}, c2, t, (%Equal.sym(D.DType, Laws.cdtype(c2), Laws.cdtype(c), ed2) : {X.Expr.type.agg.ok(X.Len{}, _) == Done{t} : E.Res(D.DType)}; (%Equal.sym(D.DType, Laws.cdtype(c), t2, ed) : {X.Expr.type.agg.ok(X.Len{}, _) == Done{t} : E.Res(D.DType)}; hok))), x => tot_true(tot, x))

# the step on a literal slot
def agg_stepc_lit(op: X.AggOp, +t2: D.DType, +h: U32, +t: D.DType, +tot: Bool, hok: {X.Expr.type.agg.ok(op, t2) == Done{t} : E.Res(D.DType)}, c: C.Column, hc: Laws.ColTy(t2, Laws.klen(V.KLit{}, h), c)) -> SResW(t, V.KAgg{}, Laws.klen(V.KAgg{}, h), tot, V.Eval.do1(h, V.IAgg{op}, V.KLit{}, c)):
  match op:""")
for op in AGGS:
    emit('    case X.%s{}:' % op)
    emit('      (ed, el) = hc')
    if op == 'Len':
        emit('      agg_len_lit(t2, h, t, tot, hok, c, ed, Laws.bcast_typed(c, h))')
    else:
        emit('      wrap_w(V.KAgg{}, t, 1, tot, True{}, V.Eval.agg(X.%s{}, c), Laws.eval_agg_typed(X.%s{}, c, t, (%%Equal.sym(D.DType, Laws.cdtype(c), t2, ed) : {X.Expr.type.agg.ok(X.%s{}, _) == Done{t} : E.Res(D.DType)}; hok)), x => tot_true(tot, x))' % (op, op, op))
goal = 'Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile(e2, V.IAgg{op} <> acc))'
emit("""
# the reducer's rule answered Done{t3} over a KRow / KScalar operand (k2): the record is (t3, KRed, tot2);
# the step lemma for the operand's slot kind comes from the caller (mk), parametric in t3
def agg_ana_t(+op: X.AggOp, +e2: X.Expr, """ + COMMON + """,
  """ + REC + """, rt: E.Res(D.DType), +ert: {X.Expr.type.agg.ok(op, t2) == rt : E.Res(D.DType)},
  +er: {A.Expr.analyse(e2, s) == Done{A.Ana{""" + REC_ARGS + """}} : E.Res(A.Ana)}, ha: {A.Ana.mk(rt, rs2, A.KRed{}, tot2, False{}) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h),
  mk: @t3: D.DType -> @hok: {X.Expr.type.agg.ok(op, t2) == Done{t3} : E.Res(D.DType)} -> @c4: C.Column -> @hc4: Laws.ColTy(t2, Laws.klen(Laws.skind(k2), h), c4) -> SResW(t3, V.KAgg{}, Laws.klen(V.KAgg{}, h), tot2, V.Eval.do1(h, V.IAgg{op}, Laws.skind(k2), c4)))
  -> """ + goal + """:
  match rt:
    case Fail{e}:
      Empty.absurd(""" + goal + """, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))
    case Done{+t3}:
      +ea = L.done_inj(A.Ana, A.Ana{t3, rs2, A.KRed{}, tot2, False{}}, A.Ana{t, rs, k, tot, loc}, ha)
      %ana_k_inj(t3, rs2, A.KRed{}, tot2, False{}, t, rs, k, tot, loc, ea) : """ + goal.replace('Laws.skind(k)', 'Laws.skind(_)') + """
      %ana_tot_inj(t3, rs2, A.KRed{}, tot2, False{}, t, rs, k, tot, loc, ea) : """ + goal.replace('Laws.skind(k), tot,', 'V.KAgg{}, _,') + """
      %ana_t_inj(t3, rs2, A.KRed{}, tot2, False{}, t, rs, k, tot, loc, ea) : """ + goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, _, V.KAgg{}, tot2,') + """
      un_run(h, V.IAgg{op}, t2, Laws.skind(k2), tot2, t3, V.KAgg{}, tot2, f, sh, stk, acc, V.Eval.compile(e2, V.IAgg{op} <> acc), ih(V.IAgg{op} <> acc, f, stk, sh, hs, hf, ev, """ + REC_ARGS + """, er), f3 => stk3 => {==}, mk(t3, ert), x => x)

# the operand's kind: a KRed operand is the nested-aggregation error; KRow / KScalar reduce
def agg_ana_k(+op: X.AggOp, +e2: X.Expr, """ + COMMON + """,
  """ + REC + """, +er: {A.Expr.analyse(e2, s) == Done{A.Ana{""" + REC_ARGS + """}} : E.Res(A.Ana)}, ha: {A.Ana.agg.k(k2, op, e2, t2, rs2, tot2) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h))
  -> """ + goal + """:
  match k2:
    case A.KRed{}:
      Empty.absurd(""" + goal + """, PV.fail_done_r(A.Ana, A.Ana.agg.k(A.KRed{}, op, e2, t2, rs2, tot2), A.Ana{t, rs, k, tot, loc}, {==}, ha))
    case A.KRow{}:
      agg_ana_t(op, e2, """ + COMMON_ARGS + """, t2, rs2, A.KRow{}, tot2, loc2, X.Expr.type.agg.ok(op, t2), {==}, er, ha, ih, t3 => hok => c4 => hc4 => agg_stepc_full(op, t2, h, t3, tot2, hok, c4, hc4))
    case A.KScalar{}:
      agg_ana_t(op, e2, """ + COMMON_ARGS + """, t2, rs2, A.KScalar{}, tot2, loc2, X.Expr.type.agg.ok(op, t2), {==}, er, ha, ih, t3 => hok => c4 => hc4 => agg_stepc_lit(op, t2, h, t3, tot2, hok, c4, hc4))

def agg_ana(+op: X.AggOp, +e2: X.Expr, """ + COMMON + """,
  r: E.Res(A.Ana), +er: {A.Expr.analyse(e2, s) == r : E.Res(A.Ana)}, ha: {A.Ana.agg(op, e2, r) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ih: IH(e2, s, h))
  -> """ + goal + """:
  match r:
    case Fail{e}:
      Empty.absurd(""" + goal + """, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))
    case Done{A.Ana{""" + ', '.join('+' + x for x in REC_ARGS.split(', ')) + """}}:
      agg_ana_k(op, e2, """ + COMMON_ARGS + """, """ + REC_ARGS + """, er, ha, ih)
""")

# ---- two- and three-operand steps -------------------------------------------------------------------------
SK = ['KFull', 'KLit', 'KAgg']
N2 = 'Bool.pick(U32, V.SKind.is_full(ka), Laws.klen(ka, h), Bool.pick(U32, V.SKind.is_full(kb), Laws.klen(kb, h), 1))'
BAD2 = 'Bool.and(Bool.and(V.SKind.is_full(ka), V.SKind.is_full(kb)), U32.is_ne(Laws.klen(ka, h), Laws.klen(kb, h)))'
N3 = 'Bool.pick(U32, V.SKind.is_full(kc), Laws.klen(kc, h), Bool.pick(U32, V.SKind.is_full(ka), Laws.klen(ka, h), Bool.pick(U32, V.SKind.is_full(kb), Laws.klen(kb, h), 1)))'
BAD3 = 'Bool.or(Bool.and(V.SKind.is_full(kc), U32.is_ne(Laws.klen(kc, h), N3)), Bool.or(Bool.and(V.SKind.is_full(ka), U32.is_ne(Laws.klen(ka, h), N3)), Bool.and(V.SKind.is_full(kb), U32.is_ne(Laws.klen(kb, h), N3))))'.replace('N3', N3)
emit("""# ---- two- and three-operand instructions (Eval.app2 / do2, Eval.app3 / do3) ------------------------------
#
# do2.a / do3.a read the operand lengths (len_k pins them to klen of the slot kinds), test the shapes
# (bad2_false / bad3_false: the test is False for typed slots) and fit the 1-row sides to the full
# length (fit_w); the result column has the length klen of the combined kind (len2 / len3).

# the length Eval.fit gives: a full column keeps its own, a 1-row side takes n
def fitlen(k: V.SKind, +m: U32, +n: U32) -> U32:
  match k:
    case V.KFull{}:
      m
    case _:
      n

def fit_lit(+n: U32, +t: D.DType, -c: C.Column, ed: {Laws.cdtype(c) == t : D.DType}, w: Laws.ColW(Laws.cdtype(c), n, V.Eval.bcast(c, n))) -> Laws.ColW(t, n, V.Eval.bcast(c, n)):
  (c2, eb, ed2, el2) = w
  (c2, eb, Equal.trans(D.DType, Laws.cdtype(c2), Laws.cdtype(c), t, ed2, ed), el2)

def fit_w(k: V.SKind, c: C.Column, +n: U32, +t: D.DType, +m: U32, hc: Laws.ColTy(t, m, c)) -> Laws.ColW(t, fitlen(k, m, n), V.Eval.fit(k, c, n)):
  match k:
    case V.KFull{}:
      (c, {==}, hc)
    case V.KLit{}:
      (ed, el) = hc
      fit_lit(n, t, c, ed, Laws.bcast_typed(c, n))
    case V.KAgg{}:
      (ed, el) = hc
      fit_lit(n, t, c, ed, Laws.bcast_typed(c, n))

# M4: fitd (do2's fit): a 1-row side next to a Dictionary operand broadcasts as a one-entry
# Dictionary (PV.bcast_dict_w), else as fit; the same dtype and length either way
def fitd_lit(+n: U32, +t: D.DType, -c: C.Column, ed: {Laws.cdtype(c) == t : D.DType}, w: Laws.ColW(Laws.cdtype(c), n, V.Eval.bcast_dict(c, n))) -> Laws.ColW(t, n, V.Eval.bcast_dict(c, n)):
  (c2, eb, ed2, el2) = w
  (c2, eb, Equal.trans(D.DType, Laws.cdtype(c2), Laws.cdtype(c), t, ed2, ed), el2)

def fitd_b(od: Bool, c: C.Column, +n: U32, +t: D.DType, ed: {Laws.cdtype(c) == t : D.DType}) -> Laws.ColW(t, n, V.Eval.fitd(V.KLit{}, c, n, od)):
  match od:
    case True{}:
      fitd_lit(n, t, c, ed, PV.bcast_dict_w(c, n))
    case False{}:
      fit_lit(n, t, c, ed, Laws.bcast_typed(c, n))

def fitd_a(od: Bool, c: C.Column, +n: U32, +t: D.DType, ed: {Laws.cdtype(c) == t : D.DType}) -> Laws.ColW(t, n, V.Eval.fitd(V.KAgg{}, c, n, od)):
  match od:
    case True{}:
      fitd_lit(n, t, c, ed, PV.bcast_dict_w(c, n))
    case False{}:
      fit_lit(n, t, c, ed, Laws.bcast_typed(c, n))

def fitd_f(od: Bool, c: C.Column, +n: U32, +t: D.DType, +m: U32, hc: Laws.ColTy(t, m, c)) -> Laws.ColW(t, m, V.Eval.fitd(V.KFull{}, c, n, od)):
  match od:
    case True{}:
      (c, {==}, hc)
    case False{}:
      (c, {==}, hc)

def fitd_w(k: V.SKind, od: Bool, c: C.Column, +n: U32, +t: D.DType, +m: U32, hc: Laws.ColTy(t, m, c)) -> Laws.ColW(t, fitlen(k, m, n), V.Eval.fitd(k, c, n, od)):
  match k:
    case V.KFull{}:
      fitd_f(od, c, n, t, m, hc)
    case V.KLit{}:
      (ed, el) = hc
      fitd_b(od, c, n, t, ed)
    case V.KAgg{}:
      (ed, el) = hc
      fitd_a(od, c, n, t, ed)

# a ColW restated as the ColTy of the witness (for the entry points)
def colw_ty(+t: D.DType, +n: U32, -c0: C.Column, -c: C.Column, ed: {Laws.cdtype(c) == t : D.DType}, w: Laws.ColW(Laws.cdtype(c), n, c0)) -> Laws.ColTy(t, n, c0):
  (c2, e, ed2, el2) = w
  %Equal.sym(C.Column, c0, c2, e) : Laws.ColTy(t, n, _)
  (Equal.trans(D.DType, Laws.cdtype(c2), Laws.cdtype(c), t, ed2, ed), el2)

# the two-operand shape test is False on typed slots (full sides have the height h)
def bad2_false(+h: U32, ka: V.SKind, kb: V.SKind) -> {""" + BAD2 + """ == False{} : Bool}:
  match ka kb:""")
for ka in SK:
    for kb in SK:
        emit('    case V.%s{} V.%s{}:' % (ka, kb))
        if ka == 'KFull' and kb == 'KFull':
            emit('      %Equal.sym(Bool, U32.is_ne(h, h), False{}, PV.u32_ne_refl(h)) : {_ == False{} : Bool}')
            emit('      {==}')
        else:
            emit('      {==}')
emit("""
# the result length of a two-operand step is klen of the combined kind
def len2(+h: U32, ka: V.SKind, kb: V.SKind) -> {fitlen(ka, Laws.klen(ka, h), """ + N2 + """) == Laws.klen(V.SKind.comb(ka, kb), h) : U32}:
  match ka kb:""")
for ka in SK:
    for kb in SK:
        emit('    case V.%s{} V.%s{}:' % (ka, kb))
        emit('      {==}')
emit("""
def bad3_false(+h: U32, kc: V.SKind, ka: V.SKind, kb: V.SKind) -> {""" + BAD3 + """ == False{} : Bool}:
  match kc ka kb:""")
for kc in SK:
    for ka in SK:
        for kb in SK:
            emit('    case V.%s{} V.%s{} V.%s{}:' % (kc, ka, kb))
            fulls = [x == 'KFull' for x in (kc, ka, kb)]
            if any(fulls):
                terms = ['_' if fl else 'False{}' for fl in fulls]
                emit('      %%Equal.sym(Bool, U32.is_ne(h, h), False{}, PV.u32_ne_refl(h)) : {Bool.or(%s, Bool.or(%s, %s)) == False{} : Bool}' % tuple(terms))
                emit('      {==}')
            else:
                emit('      {==}')
emit("""
def len3(+h: U32, kc: V.SKind, ka: V.SKind, kb: V.SKind) -> {fitlen(ka, Laws.klen(ka, h), """ + N3 + """) == Laws.klen(V.SKind.comb(kc, V.SKind.comb(ka, kb)), h) : U32}:
  match kc ka kb:""")
for kc in SK:
    for ka in SK:
        for kb in SK:
            emit('    case V.%s{} V.%s{} V.%s{}:' % (kc, ka, kb))
            emit('      {==}')

OPC = '@na2: U32 -> @nb2: U32 -> @a4: C.Column -> @b4: C.Column -> @ha4: Laws.ColTy(ta, na2, a4) -> @hb4: Laws.ColTy(tb, nb2, b4) -> Laws.ResW(True{}, t3, na2, V.Eval.op2(i, a4, b4))'
HEX2 = '@-f3: C.Frame -> @-stk3: List<&1, V.Slot> -> {V.Eval.exec(h, i, f3, stk3) == V.EvSt{f3, V.Eval.app2(i, stk3)} : V.EvSt}'
HEX3 = '@-f3: C.Frame -> @-stk3: List<&1, V.Slot> -> {V.Eval.exec(h, V.IWhen{}, f3, stk3) == V.EvSt{f3, V.Eval.app3(stk3)} : V.EvSt}'
emit("""
# a wrapped total operation result pushed (the shared tail of the two- and three-operand steps)
def do_fin(+h: U32, +K: V.SKind, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest), -r0: E.ResT(C.Column), w: Laws.ResW(True{}, t3, Laws.klen(K, h), r0)) -> PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.wrap(K, r0)):
  push_r(h, t3, K, tot, f, f3, sh, rest, ef, ev, V.Eval.wrap(K, r0), wrap_w(K, t3, Laws.klen(K, h), tot, True{}, r0, w, x => tot_true(tot, x)))

# do2.b with the shape test False: the fitted operands (ColW witnesses) go to the operation (opc)
def do2_fit2(+h: U32, +i: V.Instr, +K: V.SKind, +la: U32, +lb: U32, +ta: D.DType, +tb: D.DType, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest),
  -A: C.Column, -B: C.Column, +na: U32, +nb: U32, wa: Laws.ColW(ta, na, A), wb: Laws.ColW(tb, nb, B), ena: {na == Laws.klen(K, h) : U32},
  opc: """ + OPC + """) -> PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.do2.b(False{}, i, K, la, lb, A, B)):
  (a3, ea, tya) = wa
  (b3, eb, tyb) = wb
  %Equal.sym(C.Column, A, a3, ea) : PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.wrap(K, V.Eval.op2(i, _, B)))
  %Equal.sym(C.Column, B, b3, eb) : PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.wrap(K, V.Eval.op2(i, a3, _)))
  do_fin(h, K, t3, tot, f, f3, sh, rest, ef, ev, V.Eval.op2(i, a3, b3), resw_len(True{}, t3, Laws.klen(K, h), na, V.Eval.op2(i, a3, b3), ena, opc(na, nb, a3, b3, tya, tyb)))

def do2_fit(+h: U32, +i: V.Instr, +K: V.SKind, bad: Bool, ebad: {bad == False{} : Bool}, +la: U32, +lb: U32, +ta: D.DType, +tb: D.DType, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest),
  -A: C.Column, -B: C.Column, +na: U32, +nb: U32, wa: Laws.ColW(ta, na, A), wb: Laws.ColW(tb, nb, B), ena: {na == Laws.klen(K, h) : U32},
  opc: """ + OPC + """) -> PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.do2.b(bad, i, K, la, lb, A, B)):
  match bad:
    case True{}:
      Empty.absurd(PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.do2.b(True{}, i, K, la, lb, A, B)), L.true_false(ebad))
    case False{}:
      do2_fit2(h, i, K, la, lb, ta, tb, t3, tot, f, f3, sh, rest, ef, ev, A, B, na, nb, wa, wb, ena, opc)

# the operands' storages read (M4: is_dict, the column back unchanged): do2.e computes to do2.b
# over the symbolic shape test, each side fitted with fitd
def step2_d(+h: U32, +i: V.Instr, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest),
  -a2: C.Column, -b2: C.Column, hca: Laws.ColTy(ta, Laws.klen(ka, h), a2), hcb: Laws.ColTy(tb, Laws.klen(kb, h), b2),
  wa: &a3: C.Column -> &da: Bool -> {C.Column.is_dict(a2) == (a3, da) : C.Column & Bool} & {a3 == a2 : C.Column},
  wb: &b3: C.Column -> &db: Bool -> {C.Column.is_dict(b2) == (b3, db) : C.Column & Bool} & {b3 == b2 : C.Column},
  opc: """ + OPC + """) -> PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2.e(i, ka, kb, Laws.klen(ka, h), Laws.klen(kb, h), C.Column.is_dict(a2), C.Column.is_dict(b2))):
  (a3, +da, ea, ea2) = wa
  (b3, +db, eb, eb2) = wb
  %Equal.sym(C.Column & Bool, C.Column.is_dict(a2), (a3, da), ea) : PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2.e(i, ka, kb, Laws.klen(ka, h), Laws.klen(kb, h), _, C.Column.is_dict(b2)))
  %Equal.sym(C.Column & Bool, C.Column.is_dict(b2), (b3, db), eb) : PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2.e(i, ka, kb, Laws.klen(ka, h), Laws.klen(kb, h), (a3, da), _))
  do2_fit(h, i, V.SKind.comb(ka, kb), """ + BAD2 + """, bad2_false(h, ka, kb), Laws.klen(ka, h), Laws.klen(kb, h), ta, tb, t3, tot, f, f3, sh, rest, ef, ev, V.Eval.fitd(ka, a3, """ + N2 + """, db), V.Eval.fitd(kb, b3, """ + N2 + """, da), fitlen(ka, Laws.klen(ka, h), """ + N2 + """), fitlen(kb, Laws.klen(kb, h), """ + N2 + """), fitd_w(ka, db, a3, """ + N2 + """, ta, Laws.klen(ka, h), (%Equal.sym(C.Column, a3, a2, ea2) : Laws.ColTy(ta, Laws.klen(ka, h), _); hca)), fitd_w(kb, da, b3, """ + N2 + """, tb, Laws.klen(kb, h), (%Equal.sym(C.Column, b3, b2, eb2) : Laws.ColTy(tb, Laws.klen(kb, h), _); hcb)), len2(h, ka, kb), opc)

# the operands' lengths pinned (len_k): do2.a computes to do2.e
def step2_c(+h: U32, +i: V.Instr, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest),
  -a: C.Column, -b: C.Column, wla: &a2: C.Column -> {C.Column.len(a) == (a2, Laws.klen(ka, h)) : C.Column & U32} & Laws.ColTy(ta, Laws.klen(ka, h), a2), wlb: &b2: C.Column -> {C.Column.len(b) == (b2, Laws.klen(kb, h)) : C.Column & U32} & Laws.ColTy(tb, Laws.klen(kb, h), b2),
  opc: """ + OPC + """) -> PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2(i, ka, a, kb, b)):
  (a2, ela, hca) = wla
  (b2, elb, hcb) = wlb
  %Equal.sym(C.Column & U32, C.Column.len(a), (a2, Laws.klen(ka, h)), ela) : PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2.a(i, ka, kb, _, C.Column.len(b)))
  %Equal.sym(C.Column & U32, C.Column.len(b), (b2, Laws.klen(kb, h)), elb) : PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2.a(i, ka, kb, (a2, Laws.klen(ka, h)), _))
  step2_d(h, i, ta, ka, tb, kb, t3, tot, f, f3, sh, rest, ef, ev, a2, b2, hca, hcb, PV.isdict_w(a2), PV.isdict_w(b2), opc)

def step2_b(+h: U32, +i: V.Instr, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +t3: D.DType, +tot: Bool, -f: C.Frame, -f2: C.Frame, +sh: List<&2, Laws.Sh>, f3: C.Frame, stk2: List<&1, V.Slot>, +ef2: {f2 == f : C.Frame},
  ty: {f3 == f2 : C.Frame} & Laws.StkTy(h, Laws.Sh{tb, kb} <> Laws.Sh{ta, ka} <> sh, stk2), hex2: """ + HEX2 + """, opc: """ + OPC + """)
  -> StepW(h, i, t3, V.SKind.comb(ka, kb), tot, f, sh, V.EvSt{f3, Done{stk2}}):
  match stk2:
    case Nil{}:
      (ef3, ev) = ty
      Empty.absurd(StepW(h, i, t3, V.SKind.comb(ka, kb), tot, f, sh, V.EvSt{f3, Done{Nil{}}}), ev)
    case V.Slot{kb2, b} <> Nil{}:
      (ef3, hk, hc, ev) = ty
      Empty.absurd(StepW(h, i, t3, V.SKind.comb(ka, kb), tot, f, sh, V.EvSt{f3, Done{V.Slot{kb2, b} <> Nil{}}}), ev)
    case V.Slot{+kb2, b} <> V.Slot{+ka2, a} <> rest:
      (ef3, hkb, hcb, hka, hca, ev) = ty
      %Equal.sym(V.EvSt, V.Eval.exec(h, i, f3, V.Slot{kb2, b} <> V.Slot{ka2, a} <> rest), V.EvSt{f3, V.Eval.app2(i, V.Slot{kb2, b} <> V.Slot{ka2, a} <> rest)}, hex2(f3, V.Slot{kb2, b} <> V.Slot{ka2, a} <> rest)) : &st2: V.EvSt -> {_ == st2 : V.EvSt} & Laws.RunTy(h, t3, V.SKind.comb(ka, kb), tot, f, sh, st2)
      %Equal.sym(V.SKind, ka2, ka, hka) : PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2(i, _, a, kb2, b))
      %Equal.sym(V.SKind, kb2, kb, hkb) : PushW(h, t3, V.SKind.comb(ka, kb), tot, f, f3, sh, rest, V.Eval.do2(i, ka, a, _, b))
      step2_c(h, i, ta, ka, tb, kb, t3, tot, f, f3, sh, rest, Equal.trans(C.Frame, f3, f2, f, ef3, ef2), ev, a, b, len_k(a, Laws.klen(ka, h), ta, hca), len_k(b, Laws.klen(kb, h), tb, hcb), opc)

def step2_a(+h: U32, +i: V.Instr, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +totb: Bool, +t3: D.DType, +tot: Bool, -f: C.Frame, -f2: C.Frame, +sh: List<&2, Laws.Sh>, f3: C.Frame, r: E.ResT(List<&1, V.Slot>), +ef2: {f2 == f : C.Frame},
  ty: Laws.ResSt(h, tb, kb, totb, f2, Laws.Sh{ta, ka} <> sh, f3, r), htot: @_x: {totb == False{} : Bool} -> {tot == False{} : Bool}, hex2: """ + HEX2 + """, opc: """ + OPC + """)
  -> StepW(h, i, t3, V.SKind.comb(ka, kb), tot, f, sh, V.EvSt{f3, r}):
  match r:
    case Fail{e}:
      (V.EvSt{f3, Fail{e}}, {==}, htot(ty))
    case Done{stk2}:
      step2_b(h, i, ta, ka, tb, kb, t3, tot, f, f2, sh, f3, stk2, ef2, ty, hex2, opc)

# one two-operand instruction (IBin / IFill) on a typed state whose top two slots are the operands
def step2(+h: U32, +i: V.Instr, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +totb: Bool, +t3: D.DType, +tot: Bool, -f: C.Frame, -f2: C.Frame, +sh: List<&2, Laws.Sh>, st: V.EvSt, +ef2: {f2 == f : C.Frame},
  ty: Laws.RunTy(h, tb, kb, totb, f2, Laws.Sh{ta, ka} <> sh, st), htot: @_x: {totb == False{} : Bool} -> {tot == False{} : Bool}, hex2: """ + HEX2 + """, opc: """ + OPC + """)
  -> StepW(h, i, t3, V.SKind.comb(ka, kb), tot, f, sh, st):
  match st:
    case V.EvSt{f3, r}:
      step2_a(h, i, ta, ka, tb, kb, totb, t3, tot, f, f2, sh, f3, r, ef2, ty, htot, hex2, opc)

# ---- the three-operand step (IWhen) --------------------------------------------------------------------

def do3_fit2(+h: U32, +K: V.SKind, +n: U32, +tc: D.DType, +ta: D.DType, +tb: D.DType, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest),
  -Cc: C.Column, -A: C.Column, -B: C.Column, -nc: U32, +na: U32, -nb: U32, wc: Laws.ColW(tc, nc, Cc), wa: Laws.ColW(ta, na, A), wb: Laws.ColW(tb, nb, B), ena: {na == Laws.klen(K, h) : U32},
  hok: {X.Expr.type.when.ok(tc, ta, tb) == Done{t3} : E.Res(D.DType)}) -> PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.do3.b(False{}, K, n, Cc, A, B)):
  (c3, ec, edc, elc) = wc
  (a3, ea, eda, ela) = wa
  (b3, eb, edb, elb) = wb
  %Equal.sym(C.Column, Cc, c3, ec) : PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.wrap(K, V.Eval.when(_, A, B)))
  %Equal.sym(C.Column, A, a3, ea) : PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.wrap(K, V.Eval.when(c3, _, B)))
  %Equal.sym(C.Column, B, b3, eb) : PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.wrap(K, V.Eval.when(c3, a3, _)))
  do_fin(h, K, t3, tot, f, f3, sh, rest, ef, ev, V.Eval.when(c3, a3, b3), resw_len(True{}, t3, Laws.klen(K, h), Laws.clen(a3), V.Eval.when(c3, a3, b3), Equal.trans(U32, Laws.clen(a3), na, Laws.klen(K, h), ela, ena), Laws.eval_when_typed(c3, a3, b3, t3, (%Equal.sym(D.DType, Laws.cdtype(c3), tc, edc) : {X.Expr.type.when.ok(_, Laws.cdtype(a3), Laws.cdtype(b3)) == Done{t3} : E.Res(D.DType)}; (%Equal.sym(D.DType, Laws.cdtype(a3), ta, eda) : {X.Expr.type.when.ok(tc, _, Laws.cdtype(b3)) == Done{t3} : E.Res(D.DType)}; (%Equal.sym(D.DType, Laws.cdtype(b3), tb, edb) : {X.Expr.type.when.ok(tc, ta, _) == Done{t3} : E.Res(D.DType)}; hok))))))

def do3_fit(+h: U32, +K: V.SKind, +n: U32, bad: Bool, ebad: {bad == False{} : Bool}, +tc: D.DType, +ta: D.DType, +tb: D.DType, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest),
  -Cc: C.Column, -A: C.Column, -B: C.Column, -nc: U32, +na: U32, -nb: U32, wc: Laws.ColW(tc, nc, Cc), wa: Laws.ColW(ta, na, A), wb: Laws.ColW(tb, nb, B), ena: {na == Laws.klen(K, h) : U32},
  hok: {X.Expr.type.when.ok(tc, ta, tb) == Done{t3} : E.Res(D.DType)}) -> PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.do3.b(bad, K, n, Cc, A, B)):
  match bad:
    case True{}:
      Empty.absurd(PushW(h, t3, K, tot, f, f3, sh, rest, V.Eval.do3.b(True{}, K, n, Cc, A, B)), L.true_false(ebad))
    case False{}:
      do3_fit2(h, K, n, tc, ta, tb, t3, tot, f, f3, sh, rest, ef, ev, Cc, A, B, nc, na, nb, wc, wa, wb, ena, hok)

def step3_c(+h: U32, +tc: D.DType, +kc: V.SKind, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +t3: D.DType, +tot: Bool, -f: C.Frame, f3: C.Frame, +sh: List<&2, Laws.Sh>, rest: List<&1, V.Slot>, ef: {f3 == f : C.Frame}, ev: Laws.StkTy(h, sh, rest),
  -c: C.Column, -a: C.Column, -b: C.Column,
  wlc: &c2: C.Column -> {C.Column.len(c) == (c2, Laws.klen(kc, h)) : C.Column & U32} & Laws.ColTy(tc, Laws.klen(kc, h), c2),
  wla: &a2: C.Column -> {C.Column.len(a) == (a2, Laws.klen(ka, h)) : C.Column & U32} & Laws.ColTy(ta, Laws.klen(ka, h), a2),
  wlb: &b2: C.Column -> {C.Column.len(b) == (b2, Laws.klen(kb, h)) : C.Column & U32} & Laws.ColTy(tb, Laws.klen(kb, h), b2),
  hok: {X.Expr.type.when.ok(tc, ta, tb) == Done{t3} : E.Res(D.DType)}) -> PushW(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, f3, sh, rest, V.Eval.do3(kc, c, ka, a, kb, b)):
  (c2, elc, hcc) = wlc
  (a2, ela, hca) = wla
  (b2, elb, hcb) = wlb
  %Equal.sym(C.Column & U32, C.Column.len(c), (c2, Laws.klen(kc, h)), elc) : PushW(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, f3, sh, rest, V.Eval.do3.a(kc, ka, kb, _, C.Column.len(a), C.Column.len(b)))
  %Equal.sym(C.Column & U32, C.Column.len(a), (a2, Laws.klen(ka, h)), ela) : PushW(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, f3, sh, rest, V.Eval.do3.a(kc, ka, kb, (c2, Laws.klen(kc, h)), _, C.Column.len(b)))
  %Equal.sym(C.Column & U32, C.Column.len(b), (b2, Laws.klen(kb, h)), elb) : PushW(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, f3, sh, rest, V.Eval.do3.a(kc, ka, kb, (c2, Laws.klen(kc, h)), (a2, Laws.klen(ka, h)), _))
  do3_fit(h, V.SKind.comb(kc, V.SKind.comb(ka, kb)), """ + N3 + """, """ + BAD3 + """, bad3_false(h, kc, ka, kb), tc, ta, tb, t3, tot, f, f3, sh, rest, ef, ev, V.Eval.fit(kc, c2, """ + N3 + """), V.Eval.fit(ka, a2, """ + N3 + """), V.Eval.fit(kb, b2, """ + N3 + """), fitlen(kc, Laws.klen(kc, h), """ + N3 + """), fitlen(ka, Laws.klen(ka, h), """ + N3 + """), fitlen(kb, Laws.klen(kb, h), """ + N3 + """), fit_w(kc, c2, """ + N3 + """, tc, Laws.klen(kc, h), hcc), fit_w(ka, a2, """ + N3 + """, ta, Laws.klen(ka, h), hca), fit_w(kb, b2, """ + N3 + """, tb, Laws.klen(kb, h), hcb), len3(h, kc, ka, kb), hok)

def step3_b(+h: U32, +tc: D.DType, +kc: V.SKind, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +t3: D.DType, +tot: Bool, -f: C.Frame, -f2: C.Frame, +sh: List<&2, Laws.Sh>, f3: C.Frame, stk2: List<&1, V.Slot>, +ef2: {f2 == f : C.Frame},
  ty: {f3 == f2 : C.Frame} & Laws.StkTy(h, Laws.Sh{tb, kb} <> Laws.Sh{ta, ka} <> Laws.Sh{tc, kc} <> sh, stk2), hex3: """ + HEX3 + """, hok: {X.Expr.type.when.ok(tc, ta, tb) == Done{t3} : E.Res(D.DType)})
  -> StepW(h, V.IWhen{}, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, sh, V.EvSt{f3, Done{stk2}}):
  match stk2:
    case Nil{}:
      (ef3, ev) = ty
      Empty.absurd(StepW(h, V.IWhen{}, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, sh, V.EvSt{f3, Done{Nil{}}}), ev)
    case V.Slot{kb2, b} <> Nil{}:
      (ef3, hk, hc, ev) = ty
      Empty.absurd(StepW(h, V.IWhen{}, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, sh, V.EvSt{f3, Done{V.Slot{kb2, b} <> Nil{}}}), ev)
    case V.Slot{kb2, b} <> V.Slot{ka2, a} <> Nil{}:
      (ef3, hk, hc, hk2, hc2, ev) = ty
      Empty.absurd(StepW(h, V.IWhen{}, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, sh, V.EvSt{f3, Done{V.Slot{kb2, b} <> V.Slot{ka2, a} <> Nil{}}}), ev)
    case V.Slot{+kb2, b} <> V.Slot{+ka2, a} <> V.Slot{+kc2, c} <> rest:
      (ef3, hkb, hcb, hka, hca, hkc, hcc, ev) = ty
      %Equal.sym(V.EvSt, V.Eval.exec(h, V.IWhen{}, f3, V.Slot{kb2, b} <> V.Slot{ka2, a} <> V.Slot{kc2, c} <> rest), V.EvSt{f3, V.Eval.app3(V.Slot{kb2, b} <> V.Slot{ka2, a} <> V.Slot{kc2, c} <> rest)}, hex3(f3, V.Slot{kb2, b} <> V.Slot{ka2, a} <> V.Slot{kc2, c} <> rest)) : &st2: V.EvSt -> {_ == st2 : V.EvSt} & Laws.RunTy(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, sh, st2)
      %Equal.sym(V.SKind, kc2, kc, hkc) : PushW(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, f3, sh, rest, V.Eval.do3(_, c, ka2, a, kb2, b))
      %Equal.sym(V.SKind, ka2, ka, hka) : PushW(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, f3, sh, rest, V.Eval.do3(kc, c, _, a, kb2, b))
      %Equal.sym(V.SKind, kb2, kb, hkb) : PushW(h, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, f3, sh, rest, V.Eval.do3(kc, c, ka, a, _, b))
      step3_c(h, tc, kc, ta, ka, tb, kb, t3, tot, f, f3, sh, rest, Equal.trans(C.Frame, f3, f2, f, ef3, ef2), ev, c, a, b, len_k(c, Laws.klen(kc, h), tc, hcc), len_k(a, Laws.klen(ka, h), ta, hca), len_k(b, Laws.klen(kb, h), tb, hcb), hok)

def step3_a(+h: U32, +tc: D.DType, +kc: V.SKind, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +totb: Bool, +t3: D.DType, +tot: Bool, -f: C.Frame, -f2: C.Frame, +sh: List<&2, Laws.Sh>, f3: C.Frame, r: E.ResT(List<&1, V.Slot>), +ef2: {f2 == f : C.Frame},
  ty: Laws.ResSt(h, tb, kb, totb, f2, Laws.Sh{ta, ka} <> Laws.Sh{tc, kc} <> sh, f3, r), htot: @_x: {totb == False{} : Bool} -> {tot == False{} : Bool}, hex3: """ + HEX3 + """, hok: {X.Expr.type.when.ok(tc, ta, tb) == Done{t3} : E.Res(D.DType)})
  -> StepW(h, V.IWhen{}, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, sh, V.EvSt{f3, r}):
  match r:
    case Fail{e}:
      (V.EvSt{f3, Fail{e}}, {==}, htot(ty))
    case Done{stk2}:
      step3_b(h, tc, kc, ta, ka, tb, kb, t3, tot, f, f2, sh, f3, stk2, ef2, ty, hex3, hok)

# IWhen on a typed state whose top three slots are (b, a, c)
def step3(+h: U32, +tc: D.DType, +kc: V.SKind, +ta: D.DType, +ka: V.SKind, +tb: D.DType, +kb: V.SKind, +totb: Bool, +t3: D.DType, +tot: Bool, -f: C.Frame, -f2: C.Frame, +sh: List<&2, Laws.Sh>, st: V.EvSt, +ef2: {f2 == f : C.Frame},
  ty: Laws.RunTy(h, tb, kb, totb, f2, Laws.Sh{ta, ka} <> Laws.Sh{tc, kc} <> sh, st), htot: @_x: {totb == False{} : Bool} -> {tot == False{} : Bool}, hex3: """ + HEX3 + """, hok: {X.Expr.type.when.ok(tc, ta, tb) == Done{t3} : E.Res(D.DType)})
  -> StepW(h, V.IWhen{}, t3, V.SKind.comb(kc, V.SKind.comb(ka, kb)), tot, f, sh, st):
  match st:
    case V.EvSt{f3, r}:
      step3_a(h, tc, kc, ta, ka, tb, kb, totb, t3, tot, f, f2, sh, f3, r, ef2, ty, htot, hex3, hok)
""")


# ---- Bin / FillNull nodes ------------------------------------------------------------------------------------
OPC_L = '@na2: U32 -> @nb2: U32 -> @a4: C.Column -> @b4: C.Column -> @ha4: Laws.ColTy(ta, na2, a4) -> @hb4: Laws.ColTy(tb, nb2, b4) -> Laws.ResW(True{}, t3, na2, V.Eval.op2(i, a4, b4))'
RECA = '+ta: D.DType, +rsa: List<&2, String>, +ka: A.AKind, +tota: Bool, +loca: Bool'
RECB = '+tb: D.DType, +rsb: List<&2, String>, +kb: A.AKind, +totb: Bool, +locb: Bool'
emit("""# ---- Bin / FillNull: the left operand's code, then the right operand's from the state it left, then the step --

def bin_run_c(+h: U32, +i: V.Instr, +ta: D.DType, +ka: A.AKind, +tota: Bool, +tb: D.DType, +kb: A.AKind, +totb: Bool, +t3: D.DType, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, -code1: List<&2, V.Instr>, -f2: C.Frame, -stk1: List<&1, V.Slot>, +ef2: {f2 == f : C.Frame},
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(code1, h, V.EvSt{f2, Done{stk1}}) : V.EvSt},
  wb: Laws.RunW(h, tb, Laws.skind(kb), totb, f2, Laws.Sh{ta, Laws.skind(ka)} <> sh, stk1, i <> acc, code1), hex2: """ + HEX2 + """, opc: """ + OPC_L + """)
  -> Laws.RunW(h, t3, V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), Bool.and(tota, totb), f, sh, stk, acc, code):
  (st2, eq2, ty2) = wb
  run_step2(h, i, t3, V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), Bool.and(tota, totb), f, sh, stk, acc, code, code1, V.EvSt{f2, Done{stk1}}, st2, eq1, eq2, step2(h, i, ta, Laws.skind(ka), tb, Laws.skind(kb), totb, t3, Bool.and(tota, totb), f, f2, sh, st2, ef2, ty2, x => (%Equal.sym(Bool, totb, False{}, x) : {Bool.and(tota, _) == False{} : Bool}; PV.and_false_r(tota)), hex2, opc))

def bin_run_b(+h: U32, +i: V.Instr, +b: X.Expr, +s: List<&2, S.Field>, +ta: D.DType, +ka: A.AKind, +tota: Bool, """ + RECB + """, +t3: D.DType, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, +hs: {Laws.fschema(f) == s : List<&2, S.Field>}, +hf: {Laws.frame_ok(h, f) == True{} : Bool},
  +erb: {A.Expr.analyse(b, s) == Done{A.Ana{tb, rsb, kb, totb, locb}} : E.Res(A.Ana)}, f2: C.Frame, r1: E.ResT(List<&1, V.Slot>),
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(V.Eval.compile(b, i <> acc), h, V.EvSt{f2, r1}) : V.EvSt}, ty1: Laws.ResSt(h, ta, Laws.skind(ka), tota, f, sh, f2, r1), ihb: IH(b, s, h), hex2: """ + HEX2 + """, opc: """ + OPC_L + """)
  -> Laws.RunW(h, t3, V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), Bool.and(tota, totb), f, sh, stk, acc, code):
  match r1:
    case Fail{e}:
      run_failed(h, t3, V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), Bool.and(tota, totb), f, sh, stk, acc, code, V.Eval.compile(b, i <> acc), f2, e, eq1, (%Equal.sym(Bool, tota, False{}, ty1) : {Bool.and(_, totb) == False{} : Bool}; {==}))
    case Done{stk1}:
      (+ef2, ev1) = ty1
      bin_run_c(h, i, ta, ka, tota, tb, kb, totb, t3, f, sh, stk, acc, code, V.Eval.compile(b, i <> acc), f2, stk1, ef2, eq1, ihb(i <> acc, f2, stk1, Laws.Sh{ta, Laws.skind(ka)} <> sh, hs_along(f, f2, s, ef2, hs), hf_along(f, f2, h, ef2, hf), ev1, tb, rsb, kb, totb, locb, erb), hex2, opc)

def bin_run_a(+h: U32, +i: V.Instr, +b: X.Expr, +s: List<&2, S.Field>, +ta: D.DType, +ka: A.AKind, +tota: Bool, """ + RECB + """, +t3: D.DType, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, +hs: {Laws.fschema(f) == s : List<&2, S.Field>}, +hf: {Laws.frame_ok(h, f) == True{} : Bool},
  +erb: {A.Expr.analyse(b, s) == Done{A.Ana{tb, rsb, kb, totb, locb}} : E.Res(A.Ana)}, st1: V.EvSt,
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(V.Eval.compile(b, i <> acc), h, st1) : V.EvSt}, ty1: Laws.RunTy(h, ta, Laws.skind(ka), tota, f, sh, st1), ihb: IH(b, s, h), hex2: """ + HEX2 + """, opc: """ + OPC_L + """)
  -> Laws.RunW(h, t3, V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), Bool.and(tota, totb), f, sh, stk, acc, code):
  match st1:
    case V.EvSt{f2, r1}:
      bin_run_b(h, i, b, s, ta, ka, tota, tb, rsb, kb, totb, locb, t3, f, sh, stk, acc, code, hs, hf, erb, f2, r1, eq1, ty1, ihb, hex2, opc)

def bin_run(+h: U32, +i: V.Instr, +b: X.Expr, +s: List<&2, S.Field>, +ta: D.DType, +ka: A.AKind, +tota: Bool, """ + RECB + """, +t3: D.DType, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, +hs: {Laws.fschema(f) == s : List<&2, S.Field>}, +hf: {Laws.frame_ok(h, f) == True{} : Bool},
  +erb: {A.Expr.analyse(b, s) == Done{A.Ana{tb, rsb, kb, totb, locb}} : E.Res(A.Ana)}, wa: Laws.RunW(h, ta, Laws.skind(ka), tota, f, sh, stk, V.Eval.compile(b, i <> acc), code), ihb: IH(b, s, h), hex2: """ + HEX2 + """, opc: """ + OPC_L + """)
  -> Laws.RunW(h, t3, V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), Bool.and(tota, totb), f, sh, stk, acc, code):
  (st1, eq1, ty1) = wa
  bin_run_a(h, i, b, s, ta, ka, tota, tb, rsb, kb, totb, locb, t3, f, sh, stk, acc, code, hs, hf, erb, st1, eq1, ty1, ihb, hex2, opc)
""")
BINARY = [
    ('bin', '+op: X.BinOp, ', 'op, ', 'V.IBin{op}', 'A.Ana.bin(op, ra, rb)', 'X.Expr.type.bin.ok(op, ta, tb)',
     'X.Expr.type.bin.ok(op, _, Laws.cdtype(b))', 'X.Expr.type.bin.ok(op, ta, _)', 'Laws.eval_bin_typed(op, a, b, t3, HOK)', 'V.Eval.bin(op, a, b)'),
    ('fill', '', '', 'V.IFill{}', 'A.Ana.fill(ra, rb)', 'X.Expr.type.fill(Done{ta}, Done{tb})',
     'X.Expr.type.fill(Done{_}, Done{Laws.cdtype(b)})', 'X.Expr.type.fill(Done{ta}, Done{_})', 'Laws.eval_fill_typed(a, b, t3, HOK)', 'V.Eval.fill(a, b)'),
]
for (nm, extra, xargs, instr, ana, rule, hole_a, hole_b, law, evop) in BINARY:
    goal = 'Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile(a, V.Eval.compile(b, %s <> acc)))' % instr
    hok = "(%%Equal.sym(D.DType, Laws.cdtype(a), ta, eda) : {%s == Done{t3} : E.Res(D.DType)}; (%%Equal.sym(D.DType, Laws.cdtype(b), tb, edb) : {%s == Done{t3} : E.Res(D.DType)}; hok))" % (hole_a, hole_b)
    emit('# ---- %s ----' % nm)
    emit('')
    emit('# the operation on two typed columns, as the step hypothesis opc')
    emit('def %s_opc(%s+ta: D.DType, +tb: D.DType, +t3: D.DType, +na: U32, -nb: U32, hok: {%s == Done{t3} : E.Res(D.DType)}, a: C.Column, b: C.Column, ha: Laws.ColTy(ta, na, a), hb: Laws.ColTy(tb, nb, b)) -> Laws.ResW(True{}, t3, na, V.Eval.op2(%s, a, b)):' % (nm, extra, rule, instr))
    emit('  (eda, ela) = ha')
    emit('  (edb, elb) = hb')
    emit('  resw_len(True{}, t3, na, Laws.clen(a), %s, ela, %s)' % (evop, law.replace('HOK', hok)))
    emit('')
    emit('# the dtype rule answered Done{t3}: the record is (t3, join(ka, kb), and(tota, totb))')
    emit('def %s_ana_k(%s+a: X.Expr, +b: X.Expr, %s,' % (nm, extra, COMMON))
    emit('  %s, %s, rt: E.Res(D.DType), +ert: {%s == rt : E.Res(D.DType)},' % (RECA, RECB, rule))
    emit('  +era: {A.Expr.analyse(a, s) == Done{A.Ana{ta, rsa, ka, tota, loca}} : E.Res(A.Ana)}, +erb: {A.Expr.analyse(b, s) == Done{A.Ana{tb, rsb, kb, totb, locb}} : E.Res(A.Ana)},')
    emit('  ha: {A.Ana.mk(rt, List.append(&2, String, rsa, rsb), A.AKind.join(ka, kb), Bool.and(tota, totb), Bool.and(loca, locb)) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, iha: IH(a, s, h), ihb: IH(b, s, h))')
    emit('  -> %s:' % goal)
    emit('  match rt:')
    emit('    case Fail{e}:')
    emit('      Empty.absurd(%s, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))' % goal)
    emit('    case Done{+t3}:')
    rec = 't3, List.append(&2, String, rsa, rsb), A.AKind.join(ka, kb), Bool.and(tota, totb), Bool.and(loca, locb)'
    emit('      +ea = L.done_inj(A.Ana, A.Ana{%s}, A.Ana{t, rs, k, tot, loc}, ha)' % rec)
    emit('      %%ana_k_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, goal.replace('Laws.skind(k)', 'Laws.skind(_)')))
    emit('      %%ana_tot_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, goal.replace('Laws.skind(k), tot,', 'Laws.skind(A.AKind.join(ka, kb)), _,')))
    emit('      %%ana_t_inj(%s, t, rs, k, tot, loc, ea) : %s' % (rec, goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, _, Laws.skind(A.AKind.join(ka, kb)), Bool.and(tota, totb),')))
    emit('      %%Equal.sym(V.SKind, Laws.skind(A.AKind.join(ka, kb)), V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), skind_join(ka, kb)) : %s' % goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, t3, _, Bool.and(tota, totb),'))
    emit('      bin_run(h, %s, b, s, ta, ka, tota, tb, rsb, kb, totb, locb, t3, f, sh, stk, acc, V.Eval.compile(a, V.Eval.compile(b, %s <> acc)), hs, hf, erb, iha(V.Eval.compile(b, %s <> acc), f, stk, sh, hs, hf, ev, ta, rsa, ka, tota, loca, era), ihb, f3 => stk3 => {==}, na2 => nb2 => a4 => b4 => ha4 => hb4 => %s_opc(%sta, tb, t3, na2, nb2, ert, a4, b4, ha4, hb4))' % (instr, instr, instr, nm, xargs))
    emit('')
    emit('# the node: both operand records (the Fail rows refuted, left first), then the dtype rule')
    emit('def %s_ana(%s+a: X.Expr, +b: X.Expr, %s,' % (nm, extra, COMMON))
    emit('  ra: E.Res(A.Ana), +era: {A.Expr.analyse(a, s) == ra : E.Res(A.Ana)}, rb: E.Res(A.Ana), +erb: {A.Expr.analyse(b, s) == rb : E.Res(A.Ana)}, ha: {%s == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, iha: IH(a, s, h), ihb: IH(b, s, h))' % ana)
    emit('  -> %s:' % goal)
    emit('  match ra rb:')
    emit('    case Fail{e} _:')
    emit('      Empty.absurd(%s, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))' % goal)
    emit('    case Done{x} Fail{e}:')
    emit('      Empty.absurd(%s, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))' % goal)
    emit('    case Done{A.Ana{+ta, +rsa, +ka, +tota, +loca}} Done{A.Ana{+tb, +rsb, +kb, +totb, +locb}}:')
    emit('      %s_ana_k(%sa, b, %s, ta, rsa, ka, tota, loca, tb, rsb, kb, totb, locb, %s, {==}, era, erb, ha, iha, ihb)' % (nm, xargs, COMMON_ARGS, rule))
    emit('')

# ---- When node -------------------------------------------------------------------------------------------------
RECC = '+tc: D.DType, +rsc: List<&2, String>, +kc: A.AKind, +xc: Bool, +lc: Bool'
RECA2 = '+ta: D.DType, +rsa: List<&2, String>, +ka: A.AKind, +xa: Bool, +la: Bool'
RECB2 = '+tb: D.DType, +rsb: List<&2, String>, +kb: A.AKind, +xb: Bool, +lb: Bool'
K3 = 'V.SKind.comb(Laws.skind(kc), V.SKind.comb(Laws.skind(ka), Laws.skind(kb)))'
T3 = 'Bool.and(xc, Bool.and(xa, xb))'
WGOAL = 'Laws.RunW(h, t3, %s, %s, f, sh, stk, acc, code)' % (K3, T3)
WPARAMS = '+h: U32, +a: X.Expr, +b: X.Expr, +s: List<&2, S.Field>, ' + RECC + ', ' + RECA2 + ', ' + RECB2 + ', +t3: D.DType, -f: C.Frame, +sh: List<&2, Laws.Sh>, -stk: List<&1, V.Slot>, +acc: List<&2, V.Instr>, -code: List<&2, V.Instr>, +hs: {Laws.fschema(f) == s : List<&2, S.Field>}, +hf: {Laws.frame_ok(h, f) == True{} : Bool}, +era: {A.Expr.analyse(a, s) == Done{A.Ana{ta, rsa, ka, xa, la}} : E.Res(A.Ana)}, +erb: {A.Expr.analyse(b, s) == Done{A.Ana{tb, rsb, kb, xb, lb}} : E.Res(A.Ana)}, hok: {X.Expr.type.when.ok(tc, ta, tb) == Done{t3} : E.Res(D.DType)}'
WARGS = 'h, a, b, s, tc, rsc, kc, xc, lc, ta, rsa, ka, xa, la, tb, rsb, kb, xb, lb, t3, f, sh, stk, acc, code, hs, hf, era, erb, hok'
CODE2 = 'V.Eval.compile(b, V.IWhen{} <> acc)'
CODE1 = 'V.Eval.compile(a, %s)' % CODE2
emit("""# ---- When: c's code, then a's, then b's, then IWhen --------------------------------------------------------

# after b: the step
def when_run_f(""" + WPARAMS + """, -f3: C.Frame, -stk2: List<&1, V.Slot>, +ef3: {f3 == f : C.Frame},
  eq12: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(""" + CODE2 + """, h, V.EvSt{f3, Done{stk2}}) : V.EvSt},
  wb: Laws.RunW(h, tb, Laws.skind(kb), xb, f3, Laws.Sh{ta, Laws.skind(ka)} <> Laws.Sh{tc, Laws.skind(kc)} <> sh, stk2, V.IWhen{} <> acc, """ + CODE2 + """))
  -> """ + WGOAL + """:
  (st3, eq3, ty3) = wb
  run_step2(h, V.IWhen{}, t3, """ + K3 + """, """ + T3 + """, f, sh, stk, acc, code, """ + CODE2 + """, V.EvSt{f3, Done{stk2}}, st3, eq12, eq3, step3(h, tc, Laws.skind(kc), ta, Laws.skind(ka), tb, Laws.skind(kb), xb, t3, """ + T3 + """, f, f3, sh, st3, ef3, ty3, x => (%Equal.sym(Bool, xb, False{}, x) : {Bool.and(xc, Bool.and(xa, _)) == False{} : Bool}; (%Equal.sym(Bool, Bool.and(xa, False{}), False{}, PV.and_false_r(xa)) : {Bool.and(xc, _) == False{} : Bool}; PV.and_false_r(xc))), f4 => stk4 => {==}, hok))

# after a: its state (Fail keeps failing; Done runs b from it)
def when_run_e(""" + WPARAMS + """, -f2: C.Frame, +ef2: {f2 == f : C.Frame}, f3: C.Frame, r2: E.ResT(List<&1, V.Slot>),
  eq12: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(""" + CODE2 + """, h, V.EvSt{f3, r2}) : V.EvSt},
  ty2: Laws.ResSt(h, ta, Laws.skind(ka), xa, f2, Laws.Sh{tc, Laws.skind(kc)} <> sh, f3, r2), ihb: IH(b, s, h))
  -> """ + WGOAL + """:
  match r2:
    case Fail{e}:
      run_failed(h, t3, """ + K3 + """, """ + T3 + """, f, sh, stk, acc, code, """ + CODE2 + """, f3, e, eq12, (%Equal.sym(Bool, xa, False{}, ty2) : {Bool.and(xc, Bool.and(_, xb)) == False{} : Bool}; PV.and_false_r(xc)))
    case Done{stk2}:
      (ef32, ev2) = ty2
      +ef3 = Equal.trans(C.Frame, f3, f2, f, ef32, ef2)
      when_run_f(""" + WARGS + """, f3, stk2, ef3, eq12, ihb(V.IWhen{} <> acc, f3, stk2, Laws.Sh{ta, Laws.skind(ka)} <> Laws.Sh{tc, Laws.skind(kc)} <> sh, hs_along(f, f3, s, ef3, hs), hf_along(f, f3, h, ef3, hf), ev2, tb, rsb, kb, xb, lb, erb))

def when_run_dd(""" + WPARAMS + """, -f2: C.Frame, +ef2: {f2 == f : C.Frame}, st2: V.EvSt,
  eq12: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(""" + CODE2 + """, h, st2) : V.EvSt},
  ty2: Laws.RunTy(h, ta, Laws.skind(ka), xa, f2, Laws.Sh{tc, Laws.skind(kc)} <> sh, st2), ihb: IH(b, s, h))
  -> """ + WGOAL + """:
  match st2:
    case V.EvSt{f3, r2}:
      when_run_e(""" + WARGS + """, f2, ef2, f3, r2, eq12, ty2, ihb)

def when_run_d(""" + WPARAMS + """, -f2: C.Frame, -stk1: List<&1, V.Slot>, +ef2: {f2 == f : C.Frame},
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(""" + CODE1 + """, h, V.EvSt{f2, Done{stk1}}) : V.EvSt},
  wa: Laws.RunW(h, ta, Laws.skind(ka), xa, f2, Laws.Sh{tc, Laws.skind(kc)} <> sh, stk1, """ + CODE2 + """, """ + CODE1 + """), ihb: IH(b, s, h))
  -> """ + WGOAL + """:
  (st2, eq2, ty2) = wa
  when_run_dd(""" + WARGS + """, f2, ef2, st2, Equal.trans(V.EvSt, V.Eval.run(code, h, V.EvSt{f, Done{stk}}), V.Eval.run(""" + CODE1 + """, h, V.EvSt{f2, Done{stk1}}), V.Eval.run(""" + CODE2 + """, h, st2), eq1, eq2), ty2, ihb)

# after c: its state (Fail keeps failing; Done runs a from it)
def when_run_b(""" + WPARAMS + """, f2: C.Frame, r1: E.ResT(List<&1, V.Slot>),
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(""" + CODE1 + """, h, V.EvSt{f2, r1}) : V.EvSt},
  ty1: Laws.ResSt(h, tc, Laws.skind(kc), xc, f, sh, f2, r1), iha: IH(a, s, h), ihb: IH(b, s, h))
  -> """ + WGOAL + """:
  match r1:
    case Fail{e}:
      run_failed(h, t3, """ + K3 + """, """ + T3 + """, f, sh, stk, acc, code, """ + CODE1 + """, f2, e, eq1, (%Equal.sym(Bool, xc, False{}, ty1) : {Bool.and(_, Bool.and(xa, xb)) == False{} : Bool}; {==}))
    case Done{stk1}:
      (+ef2, ev1) = ty1
      when_run_d(""" + WARGS + """, f2, stk1, ef2, eq1, iha(""" + CODE2 + """, f2, stk1, Laws.Sh{tc, Laws.skind(kc)} <> sh, hs_along(f, f2, s, ef2, hs), hf_along(f, f2, h, ef2, hf), ev1, ta, rsa, ka, xa, la, era), ihb)

def when_run_a(""" + WPARAMS + """, st1: V.EvSt,
  eq1: {V.Eval.run(code, h, V.EvSt{f, Done{stk}}) == V.Eval.run(""" + CODE1 + """, h, st1) : V.EvSt},
  ty1: Laws.RunTy(h, tc, Laws.skind(kc), xc, f, sh, st1), iha: IH(a, s, h), ihb: IH(b, s, h))
  -> """ + WGOAL + """:
  match st1:
    case V.EvSt{f2, r1}:
      when_run_b(""" + WARGS + """, f2, r1, eq1, ty1, iha, ihb)

def when_run(""" + WPARAMS + """, wc: Laws.RunW(h, tc, Laws.skind(kc), xc, f, sh, stk, """ + CODE1 + """, code), iha: IH(a, s, h), ihb: IH(b, s, h))
  -> """ + WGOAL + """:
  (st1, eq1, ty1) = wc
  when_run_a(""" + WARGS + """, st1, eq1, ty1, iha, ihb)
""")
goal = 'Laws.RunW(h, t, Laws.skind(k), tot, f, sh, stk, acc, V.Eval.compile(c, V.Eval.compile(a, V.Eval.compile(b, V.IWhen{} <> acc))))'
rec = 't3, List.append(&2, String, rsc, List.append(&2, String, rsa, rsb)), A.AKind.join(kc, A.AKind.join(ka, kb)), Bool.and(xc, Bool.and(xa, xb)), Bool.and(lc, Bool.and(la, lb))'
emit("""# the dtype rule answered Done{t3}: the record is (t3, join(kc, join(ka, kb)), and(xc, and(xa, xb)))
def when_ana_k(+c: X.Expr, +a: X.Expr, +b: X.Expr, """ + COMMON + """,
  """ + RECC + """, """ + RECA2 + """, """ + RECB2 + """, rt: E.Res(D.DType), +ert: {X.Expr.type.when.ok(tc, ta, tb) == rt : E.Res(D.DType)},
  +erc: {A.Expr.analyse(c, s) == Done{A.Ana{tc, rsc, kc, xc, lc}} : E.Res(A.Ana)}, +era: {A.Expr.analyse(a, s) == Done{A.Ana{ta, rsa, ka, xa, la}} : E.Res(A.Ana)}, +erb: {A.Expr.analyse(b, s) == Done{A.Ana{tb, rsb, kb, xb, lb}} : E.Res(A.Ana)},
  ha: {A.Ana.mk(rt, List.append(&2, String, rsc, List.append(&2, String, rsa, rsb)), A.AKind.join(kc, A.AKind.join(ka, kb)), Bool.and(xc, Bool.and(xa, xb)), Bool.and(lc, Bool.and(la, lb))) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)},
  ihc: IH(c, s, h), iha: IH(a, s, h), ihb: IH(b, s, h))
  -> """ + goal + """:
  match rt:
    case Fail{e}:
      Empty.absurd(""" + goal + """, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))
    case Done{+t3}:
      +ea = L.done_inj(A.Ana, A.Ana{""" + rec + """}, A.Ana{t, rs, k, tot, loc}, ha)
      %ana_k_inj(""" + rec + """, t, rs, k, tot, loc, ea) : """ + goal.replace('Laws.skind(k)', 'Laws.skind(_)') + """
      %ana_tot_inj(""" + rec + """, t, rs, k, tot, loc, ea) : """ + goal.replace('Laws.skind(k), tot,', 'Laws.skind(A.AKind.join(kc, A.AKind.join(ka, kb))), _,') + """
      %ana_t_inj(""" + rec + """, t, rs, k, tot, loc, ea) : """ + goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, _, Laws.skind(A.AKind.join(kc, A.AKind.join(ka, kb))), Bool.and(xc, Bool.and(xa, xb)),') + """
      %Equal.sym(V.SKind, Laws.skind(A.AKind.join(kc, A.AKind.join(ka, kb))), V.SKind.comb(Laws.skind(kc), Laws.skind(A.AKind.join(ka, kb))), skind_join(kc, A.AKind.join(ka, kb))) : """ + goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, t3, _, Bool.and(xc, Bool.and(xa, xb)),') + """
      %Equal.sym(V.SKind, Laws.skind(A.AKind.join(ka, kb)), V.SKind.comb(Laws.skind(ka), Laws.skind(kb)), skind_join(ka, kb)) : """ + goal.replace('Laws.RunW(h, t, Laws.skind(k), tot,', 'Laws.RunW(h, t3, V.SKind.comb(Laws.skind(kc), _), Bool.and(xc, Bool.and(xa, xb)),') + """
      when_run(h, a, b, s, tc, rsc, kc, xc, lc, ta, rsa, ka, xa, la, tb, rsb, kb, xb, lb, t3, f, sh, stk, acc, """ + 'V.Eval.compile(c, %s)' % CODE1 + """, hs, hf, era, erb, ert, ihc(""" + CODE1 + """, f, stk, sh, hs, hf, ev, tc, rsc, kc, xc, lc, erc), iha, ihb)

# the node: the three operand records (the Fail rows refuted, left to right), then the dtype rule
def when_ana(+c: X.Expr, +a: X.Expr, +b: X.Expr, """ + COMMON + """,
  rc: E.Res(A.Ana), +erc: {A.Expr.analyse(c, s) == rc : E.Res(A.Ana)}, ra: E.Res(A.Ana), +era: {A.Expr.analyse(a, s) == ra : E.Res(A.Ana)}, rb: E.Res(A.Ana), +erb: {A.Expr.analyse(b, s) == rb : E.Res(A.Ana)},
  ha: {A.Ana.when(rc, ra, rb) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, ihc: IH(c, s, h), iha: IH(a, s, h), ihb: IH(b, s, h))
  -> """ + goal + """:
  match rc ra rb:
    case Fail{e} _ _:
      Empty.absurd(""" + goal + """, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))
    case Done{x} Fail{e} _:
      Empty.absurd(""" + goal + """, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))
    case Done{x} Done{y} Fail{e}:
      Empty.absurd(""" + goal + """, L.fail_done(A.Ana, e, A.Ana{t, rs, k, tot, loc}, ha))
    case Done{A.Ana{+tc, +rsc, +kc, +xc, +lc}} Done{A.Ana{+ta, +rsa, +ka, +xa, +la}} Done{A.Ana{+tb, +rsb, +kb, +xb, +lb}}:
      when_ana_k(c, a, b, """ + COMMON_ARGS + """, tc, rsc, kc, xc, lc, ta, rsa, ka, xa, la, tb, rsb, kb, xb, lb, X.Expr.type.when.ok(tc, ta, tb), {==}, erc, era, erb, ha, ihc, iha, ihb)
""")

# ---- the law: induction over the expression ------------------------------------------------------------------
def IHL(x):
    return 'acc2 => f2 => stk2 => sh2 => hs2 => hf2 => ev2 => t2 => rs2 => k2 => tot2 => loc2 => ha2 => Laws.run_typed(%s, s, h, acc2, f2, stk2, sh2, hs2, hf2, ev2, t2, rs2, k2, tot2, loc2, ha2)' % x
emit("""# ---- the law: induction over the expression, the IH as a lambda over the operand -------------------------

def Laws.run_typed(e, s, h, acc, f, stk, sh, hs, hf, ev, t, rs, k, tot, loc, ha):
  match e:
    case X.Col{+n}:
      col_ana(n, """ + COMMON_ARGS + """, S.Schema.find(s, n), {==}, ha)
    case X.Lit{+v}:
      lit_ana(v, h, acc, f, stk, sh, ev, t, rs, k, tot, loc, ha)
    case X.Alias{e2, n}:
      Laws.run_typed(e2, s, h, acc, f, stk, sh, hs, hf, ev, t, rs, k, tot, loc, ha)
    case X.Cast{+e2, +to}:
      cast_ana(to, e2, """ + COMMON_ARGS + """, X.Expr.is_null_lit(e2), A.Expr.analyse(e2, s), {==}, ha, """ + IHL('e2') + """)
    case X.TryCast{+e2, +to}:
      trycast_ana(to, e2, """ + COMMON_ARGS + """, X.Expr.is_null_lit(e2), A.Expr.analyse(e2, s), {==}, ha, """ + IHL('e2') + """)
    case X.Un{+op, +e2}:
      un_ana(op, e2, """ + COMMON_ARGS + """, A.Expr.analyse(e2, s), {==}, ha, """ + IHL('e2') + """)
    case X.Bin{+op, +a, +b}:
      bin_ana(op, a, b, """ + COMMON_ARGS + """, A.Expr.analyse(a, s), {==}, A.Expr.analyse(b, s), {==}, ha, """ + IHL('a') + """, """ + IHL('b') + """)
    case X.FillNull{+a, +b}:
      fill_ana(a, b, """ + COMMON_ARGS + """, A.Expr.analyse(a, s), {==}, A.Expr.analyse(b, s), {==}, ha, """ + IHL('a') + """, """ + IHL('b') + """)
    case X.Agg{+op, +e2}:
      agg_ana(op, e2, """ + COMMON_ARGS + """, A.Expr.analyse(e2, s), {==}, ha, """ + IHL('e2') + """)
    case X.When{+c, +a, +b}:
      when_ana(c, a, b, """ + COMMON_ARGS + """, A.Expr.analyse(c, s), {==}, A.Expr.analyse(a, s), {==}, A.Expr.analyse(b, s), {==}, ha, """ + IHL('c') + """, """ + IHL('a') + """, """ + IHL('b') + """)
    case X.IsIn{+e2, +vs}:
      isin_ana(vs, e2, """ + COMMON_ARGS + """, A.Expr.analyse(e2, s), {==}, ha, """ + IHL('e2') + """)
    case X.Clip{+e2, +lo, +hi}:
      clip_ana(lo, hi, e2, """ + COMMON_ARGS + """, A.Expr.analyse(e2, s), {==}, ha, """ + IHL('e2') + """)
    case X.StrPred{+op, +e2, +p}:
      strpred_ana(op, p, e2, """ + COMMON_ARGS + """, A.Expr.analyse(e2, s), {==}, ha, """ + IHL('e2') + """)

# ---- the entry points: Eval.full (every 1-row result broadcast) and Eval.expr (a reduction stays 1 row) --------

# the height of the entry point's answer: Eval.full gives the frame's height, Eval.expr elen of the kind
def mlen(full: Bool, k: A.AKind, +h: U32) -> U32:
  match full:
    case True{}:
      h
    case False{}:
      Laws.elen(k, h)

# the slot's column fitted by Eval.unslot has the kind's height
def mode_k(full: Bool, k: A.AKind, +h: U32, +hh: U32, +t: D.DType, +eh: {h == hh : U32}, c: C.Column, hc: Laws.ColTy(t, Laws.klen(Laws.skind(k), h), c)) -> Laws.ColTy(t, mlen(full, k, hh), V.Eval.fit(V.Eval.unslot.k(full, Laws.skind(k)), c, hh)):
  match full k:
    case True{} A.KRow{}:
      (ed, el) = hc
      (ed, Equal.trans(U32, Laws.clen(c), h, hh, el, eh))
    case True{} A.KScalar{}:
      (+ed, el) = hc
      colw_ty(t, hh, V.Eval.bcast(c, hh), c, ed, Laws.bcast_typed(c, hh))
    case True{} A.KRed{}:
      (+ed, el) = hc
      colw_ty(t, hh, V.Eval.bcast(c, hh), c, ed, Laws.bcast_typed(c, hh))
    case False{} A.KRow{}:
      (ed, el) = hc
      (ed, Equal.trans(U32, Laws.clen(c), h, hh, el, eh))
    case False{} A.KScalar{}:
      (+ed, el) = hc
      colw_ty(t, hh, V.Eval.bcast(c, hh), c, ed, Laws.bcast_typed(c, hh))
    case False{} A.KRed{}:
      hc

# Frame.height with the height as a Data value beside the frame
def height_dup(f: C.Frame) -> &f2: C.Frame -> &n: U32 -> {n == Laws.fheight(f) : U32} & {C.Frame.height(f) == (f2, n) : C.Frame & U32} & {f2 == f : C.Frame}:
  match f:
    case C.Frame{+h, cols}:
      (C.Frame{h, cols}, h, {==}, {==}, {==})

# the final state's single slot: Eval.unslot fits it to the height
def mode_fin_d(+full: Bool, +h: U32, +t: D.DType, +k: A.AKind, +tot: Bool, -f2: C.Frame, -f5: C.Frame, f6: C.Frame, +hn: U32, +e52: {f5 == f2 : C.Frame}, +eh: {h == Laws.fheight(f2) : U32}, +en: {hn == Laws.fheight(f5) : U32}, ef6: {f6 == f5 : C.Frame}, +k2: V.SKind, c: C.Column, rest: List<&1, V.Slot>,
  hk: {k2 == Laws.skind(k) : V.SKind}, hc: Laws.ColTy(t, Laws.klen(Laws.skind(k), h), c), ev: Laws.StkTy(h, Nil{}, rest))
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.b(full, V.Eval.fin.one(V.Slot{k2, c} <> rest), (f6, hn))):
  match rest:
    case x <> xs:
      Empty.absurd(Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.b(full, V.Eval.fin.one(V.Slot{k2, c} <> x <> xs), (f6, hn))), ev)
    case Nil{}:
      %e52 : Laws.EvalTyR(t, tot, mlen(full, k, Laws.fheight(_)), _, f6, Done{V.Eval.fit(V.Eval.unslot.k(full, k2), c, hn)})
      %en : Laws.EvalTyR(t, tot, mlen(full, k, _), f5, f6, Done{V.Eval.fit(V.Eval.unslot.k(full, k2), c, hn)})
      %Equal.sym(V.SKind, k2, Laws.skind(k), hk) : Laws.EvalTyR(t, tot, mlen(full, k, hn), f5, f6, Done{V.Eval.fit(V.Eval.unslot.k(full, _), c, hn)})
      (ef6, mode_k(full, k, h, hn, t, Equal.trans(U32, h, Laws.fheight(f2), hn, eh, Equal.trans(U32, Laws.fheight(f2), Laws.fheight(f5), hn, (%e52 : {Laws.fheight(_) == Laws.fheight(f5) : U32}; {==}), Equal.sym(U32, hn, Laws.fheight(f5), en))), c, hc))

def mode_fin_c(+full: Bool, +h: U32, +t: D.DType, +k: A.AKind, +tot: Bool, -f2: C.Frame, -f5: C.Frame, f6: C.Frame, +hn: U32, +e52: {f5 == f2 : C.Frame}, +eh: {h == Laws.fheight(f2) : U32}, +en: {hn == Laws.fheight(f5) : U32}, ef6: {f6 == f5 : C.Frame}, stk: List<&1, V.Slot>, ev: Laws.StkTy(h, Laws.Sh{t, Laws.skind(k)} <> Nil{}, stk))
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.b(full, V.Eval.fin.one(stk), (f6, hn))):
  match stk:
    case Nil{}:
      Empty.absurd(Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.b(full, V.Eval.fin.one(Nil{}), (f6, hn))), ev)
    case V.Slot{+k2, c} <> rest:
      (hk, hc, ev2) = ev
      mode_fin_d(full, h, t, k, tot, f2, f5, f6, hn, e52, eh, en, ef6, k2, c, rest, hk, hc, ev2)

# the final state's result: a failure the analysis allowed, or the slot
def mode_fin_bb(+full: Bool, +h: U32, +t: D.DType, +k: A.AKind, +tot: Bool, -f2: C.Frame, -f4: C.Frame, -f5: C.Frame, f6: C.Frame, +hn: U32, +e42: {f4 == f2 : C.Frame}, +eh: {h == Laws.fheight(f2) : U32}, +en: {hn == Laws.fheight(f5) : U32}, ef6: {f6 == f5 : C.Frame}, r: E.ResT(List<&1, V.Slot>), ty: Laws.ResSt(h, t, Laws.skind(k), tot, f4, Nil{}, f5, r))
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.b(full, V.Eval.fin.r(r), (f6, hn))):
  match r:
    case Fail{e}:
      ty
    case Done{stk}:
      (ef5, ev) = ty
      mode_fin_c(full, h, t, k, tot, f2, f5, f6, hn, Equal.trans(C.Frame, f5, f4, f2, ef5, e42), eh, en, ef6, stk, ev)

def mode_fin_b(+full: Bool, +h: U32, +t: D.DType, +k: A.AKind, +tot: Bool, -f2: C.Frame, -f4: C.Frame, -f5: C.Frame, +e42: {f4 == f2 : C.Frame}, +eh: {h == Laws.fheight(f2) : U32}, r: E.ResT(List<&1, V.Slot>), ty: Laws.ResSt(h, t, Laws.skind(k), tot, f4, Nil{}, f5, r),
  w: &f6: C.Frame -> &n: U32 -> {n == Laws.fheight(f5) : U32} & {C.Frame.height(f5) == (f6, n) : C.Frame & U32} & {f6 == f5 : C.Frame})
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.b(full, V.Eval.fin.r(r), C.Frame.height(f5))):
  (f6, +hn, +en, eh5, ef6) = w
  %Equal.sym(C.Frame & U32, C.Frame.height(f5), (f6, hn), eh5) : Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.b(full, V.Eval.fin.r(r), _))
  mode_fin_bb(full, h, t, k, tot, f2, f4, f5, f6, hn, e42, eh, en, ef6, r, ty)

def mode_fin(+full: Bool, +h: U32, +t: D.DType, +k: A.AKind, +tot: Bool, -f2: C.Frame, -f4: C.Frame, +e42: {f4 == f2 : C.Frame}, +eh: {h == Laws.fheight(f2) : U32}, st: V.EvSt, ty: Laws.RunTy(h, t, Laws.skind(k), tot, f4, Nil{}, st))
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.fin(st))):
  match st:
    case V.EvSt{f5, r}:
      mode_fin_b(full, h, t, k, tot, f2, f4, f5, e42, eh, r, ty, height_dup(f5))

# the run of the code from the empty stack (run_typed at acc = Nil, sh = Nil)
def full_e(+full: Bool, -f2: C.Frame, +e: X.Expr, +t: D.DType, +k: A.AKind, +tot: Bool, -f4: C.Frame, +h: U32, +e42: {f4 == f2 : C.Frame}, +eh: {h == Laws.fheight(f2) : U32}, w: Laws.RunW(h, t, Laws.skind(k), tot, f4, Nil{}, Nil{}, Nil{}, V.Eval.compile(e, Nil{})))
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.fin(V.Eval.run(V.Eval.compile(e, Nil{}), h, V.EvSt{f4, Done{Nil{}}})))):
  (st, eq, ty) = w
  %Equal.sym(V.EvSt, V.Eval.run(V.Eval.compile(e, Nil{}), h, V.EvSt{f4, Done{Nil{}}}), st, eq) : Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.fin(_)))
  mode_fin(full, h, t, k, tot, f2, f4, e42, eh, st, ty)

# ---- Frame.schema with the schema as a Data value (the law needs the schema term live) -------------------

def dt_col(-c2: C.Column, -col: C.Column, +dt: D.DType, e2: {c2 == col : C.Column}, edt: {dt == Laws.cdtype(c2) : D.DType}) -> {dt == Laws.cdtype(col) : D.DType}:
  %e2 : {dt == Laws.cdtype(_) : D.DType}
  edt

def CSchD(-cols: List<&1, C.Named>) -> Type:
  &cols2: List<&1, C.Named> -> &s: List<&2, S.Field> -> {s == Laws.cschema(cols) : List<&2, S.Field>} & {S.Cols.schema(cols) == (cols2, s) : List<&1, C.Named> & List<&2, S.Field>} & {cols2 == cols : List<&1, C.Named>}

def CSchG(+n: String, -col: C.Column, -rest: List<&1, C.Named>, -cr: C.Column & D.DType, -r: List<&1, C.Named> & List<&2, S.Field>) -> Type:
  &cols2: List<&1, C.Named> -> &s2: List<&2, S.Field> -> {s2 == Laws.cschema(C.Named{n, col} <> rest) : List<&2, S.Field>} & {S.Cols.schema.k(n, cr, r) == (cols2, s2) : List<&1, C.Named> & List<&2, S.Field>} & {cols2 == C.Named{n, col} <> rest : List<&1, C.Named>}

def cschema_dup_cons2(+n: String, -col: C.Column, -rest: List<&1, C.Named>, -c2: C.Column, e1: {C.Column.dtype(col) == (c2, Laws.cdtype(col)) : C.Column & D.DType}, +e2: {c2 == col : C.Column}, cols3: List<&1, C.Named>, +s: List<&2, S.Field>, es: {s == Laws.cschema(rest) : List<&2, S.Field>}, eq: {S.Cols.schema(rest) == (cols3, s) : List<&1, C.Named> & List<&2, S.Field>}, ecols: {cols3 == rest : List<&1, C.Named>},
  wd: &c3: C.Column -> &k: U32 -> &dt: D.DType -> {c3 == c2 : C.Column} & {dt == Laws.cdtype(c2) : D.DType} & {k == Laws.clen(c2) : U32}) -> CSchD(C.Named{n, col} <> rest):
  (c3, +k, +dt, +ec3, +edt, ek) = wd
  %Equal.sym(C.Column & D.DType, C.Column.dtype(col), (c2, Laws.cdtype(col)), e1) : CSchG(n, col, rest, _, S.Cols.schema(rest))
  %Equal.sym(List<&1, C.Named> & List<&2, S.Field>, S.Cols.schema(rest), (cols3, s), eq) : CSchG(n, col, rest, (c2, Laws.cdtype(col)), _)
  %ec3 : CSchG(n, col, rest, (_, Laws.cdtype(col)), (cols3, s))
  %dt_col(c2, col, dt, e2, edt) : CSchG(n, col, rest, (c3, _), (cols3, s))
  (C.Named{n, c3} <> cols3, S.Field{n, dt} <> s, (%dt_col(c2, col, dt, e2, edt) : {S.Field{n, dt} <> s == S.Field{n, _} <> Laws.cschema(rest) : List<&2, S.Field>}; (%es : {S.Field{n, dt} <> s == S.Field{n, dt} <> _ : List<&2, S.Field>}; {==})), {==}, (%Equal.trans(C.Column, c3, c2, col, ec3, e2) : {C.Named{n, c3} <> cols3 == C.Named{n, _} <> rest : List<&1, C.Named>}; (%ecols : {C.Named{n, c3} <> cols3 == C.Named{n, c3} <> _ : List<&1, C.Named>}; {==})))

def cschema_dup_cons(+n: String, -col: C.Column, -rest: List<&1, C.Named>, wd: Laws.DtypeW(col), w: CSchD(rest)) -> CSchD(C.Named{n, col} <> rest):
  (c2, e1, e2) = wd
  (cols3, +s, es, eq, ecols) = w
  cschema_dup_cons2(n, col, rest, c2, e1, e2, cols3, s, es, eq, ecols, PV.col_dup2(c2))

def cschema_dup(cols: List<&1, C.Named>) -> CSchD(cols):
  match cols:
    case Nil{}:
      (Nil{}, Nil{}, {==}, {==}, {==})
    case C.Named{+n, col} <> rest:
      cschema_dup_cons(n, col, rest, Laws.dtype_w(col), cschema_dup(rest))

def SchD(-f: C.Frame) -> Type:
  &f2: C.Frame -> &s: List<&2, S.Field> -> {f2 == f : C.Frame} & {s == Laws.fschema(f) : List<&2, S.Field>} & {S.Frame.schema(f) == (f2, s) : C.Frame & List<&2, S.Field>}

def schema_dup_k(+h: U32, -cols: List<&1, C.Named>, w: CSchD(cols)) -> SchD(C.Frame{h, cols}):
  (cols2, +s, es, eq, ecols) = w
  %Equal.sym(List<&1, C.Named> & List<&2, S.Field>, S.Cols.schema(cols), (cols2, s), eq) : &f2: C.Frame -> &s2: List<&2, S.Field> -> {f2 == C.Frame{h, cols} : C.Frame} & {s2 == Laws.cschema(cols) : List<&2, S.Field>} & {S.Frame.schema.k(h, _) == (f2, s2) : C.Frame & List<&2, S.Field>}
  (C.Frame{h, cols2}, s, (%ecols : {C.Frame{h, cols2} == C.Frame{h, _} : C.Frame}; {==}), es, {==})

def schema_dup(f: C.Frame) -> SchD(f):
  match f:
    case C.Frame{+h, cols}:
      schema_dup_k(h, cols, cschema_dup(cols))

# the analysis hypothesis over the schema as a Data value
def ana_along_s(-f2: C.Frame, +s: List<&2, S.Field>, +e: X.Expr, +t: D.DType, +rs: List<&2, String>, +k: A.AKind, +tot: Bool, +loc: Bool, es: {s == Laws.fschema(f2) : List<&2, S.Field>}, ha: {A.Expr.analyse(e, Laws.fschema(f2)) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}) -> {A.Expr.analyse(e, s) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}:
  %Equal.sym(List<&2, S.Field>, s, Laws.fschema(f2), es) : {A.Expr.analyse(e, _) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}
  ha

# Frame.height taken (height_dup): the run from the frame copy with the height as a number
def full_c(+full: Bool, -f2: C.Frame, +e: X.Expr, +s: List<&2, S.Field>, +t: D.DType, +rs: List<&2, String>, +k: A.AKind, +tot: Bool, +loc: Bool, hok: {Laws.frame_ok(Laws.fheight(f2), f2) == True{} : Bool}, ha: {A.Expr.analyse(e, s) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, es: {s == Laws.fschema(f2) : List<&2, S.Field>}, -f3: C.Frame, +e32: {f3 == f2 : C.Frame},
  w: &f4: C.Frame -> &n: U32 -> {n == Laws.fheight(f3) : U32} & {C.Frame.height(f3) == (f4, n) : C.Frame & U32} & {f4 == f3 : C.Frame})
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.slot.h(e, C.Frame.height(f3)))):
  (f4, +hn, en, eh3, ef4) = w
  %Equal.sym(C.Frame & U32, C.Frame.height(f3), (f4, hn), eh3) : Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.slot.h(e, _)))
  +e42 = Equal.trans(C.Frame, f4, f3, f2, ef4, e32)
  +eh = Equal.trans(U32, hn, Laws.fheight(f3), Laws.fheight(f2), en, (%Equal.sym(C.Frame, f3, f2, e32) : {Laws.fheight(_) == Laws.fheight(f2) : U32}; {==}))
  full_e(full, f2, e, t, k, tot, f4, hn, e42, eh, Laws.run_typed(e, s, hn, Nil{}, f4, Nil{}, Nil{}, (%Equal.sym(C.Frame, f4, f2, e42) : {Laws.fschema(_) == s : List<&2, S.Field>}; Equal.sym(List<&2, S.Field>, s, Laws.fschema(f2), es)), (%Equal.sym(C.Frame, f4, f2, e42) : {Laws.frame_ok(hn, _) == True{} : Bool}; (%Equal.sym(U32, hn, Laws.fheight(f2), eh) : {Laws.frame_ok(_, f2) == True{} : Bool}; hok)), Unit{}, t, rs, k, tot, loc, ha))

# Frame.schema taken (schema_dup): the analysis' Done record is the type check's answer
def full_b(+full: Bool, -f2: C.Frame, +e: X.Expr, +t: D.DType, +rs: List<&2, String>, +k: A.AKind, +tot: Bool, +loc: Bool, hok: {Laws.frame_ok(Laws.fheight(f2), f2) == True{} : Bool}, ha: {A.Expr.analyse(e, Laws.fschema(f2)) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, w: SchD(f2))
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.slot(f2, e))):
  (f3, +s, +e32, +es, eq) = w
  +ha2 = ana_along_s(f2, s, e, t, rs, k, tot, loc, es, ha)
  %Equal.sym(C.Frame & List<&2, S.Field>, S.Frame.schema(f2), (f3, s), eq) : Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.slot.s(e, _)))
  %Equal.sym(E.Res(A.Ana), A.Expr.analyse(e, s), Done{A.Ana{t, rs, k, tot, loc}}, ha2) : Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f2)), f2, V.Eval.mode.a(full, V.Eval.slot.t(e, f3, A.Ana.type.k(_))))
  full_c(full, f2, e, s, t, rs, k, tot, loc, hok, ha2, es, f3, e32, height_dup(f3))

# the WF bridge taken (wf_frame_ok_w): the frame copy carries the shape facts
def full_a(+full: Bool, -f: C.Frame, +e: X.Expr, +t: D.DType, +rs: List<&2, String>, +k: A.AKind, +tot: Bool, +loc: Bool, ha: {A.Expr.analyse(e, Laws.fschema(f)) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}, w: PV.WfOkW(f))
  -> Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(f)), f, V.Eval.mode.a(full, V.Eval.slot(f, e))):
  (f2, +ef, hok) = w
  %ef : Laws.EvalTy(t, tot, mlen(full, k, Laws.fheight(_)), _, V.Eval.mode.a(full, V.Eval.slot(_, e)))
  full_b(full, f2, e, t, rs, k, tot, loc, hok, (%Equal.sym(C.Frame, f2, f, ef) : {A.Expr.analyse(e, Laws.fschema(_)) == Done{A.Ana{t, rs, k, tot, loc}} : E.Res(A.Ana)}; ha), schema_dup(f2))

def Laws.eval_full_typed(f, e, wf, t, rs, k, tot, loc, ha):
  full_a(True{}, f, e, t, rs, k, tot, loc, ha, PV.wf_frame_ok_w(f, wf))

def Laws.eval_expr_typed(f, e, wf, t, rs, k, tot, loc, ha):
  full_a(False{}, f, e, t, rs, k, tot, loc, ha, PV.wf_frame_ok_w(f, wf))
""")

